                  </div>
                  <div className="p-3 bg-slate-800 rounded-xl">
                      <TrendingUp className="w-5 h-5 text-indigo-400" />
                  </div>
              </div>

              <div className="space-y-3">
                  <h4 className="text-slate-500 text-[10px] font-bold uppercase tracking-wider px-1">Insights</h4>
                  {analysis.insights.map((insight, idx) => (
                      <div key={idx} className="p-4 bg-slate-900 rounded-xl border border-white/5">
                          <div className="flex items-center gap-2 mb-1">
                              {insight.type === 'success' && <CheckCircle className="w-3 h-3 text-emerald-400" />}
                              {insight.type === 'warning' && <AlertTriangle className="w-3 h-3 text-amber-400" />}
                              {insight.type === 'critical' && <ShieldAlert className="w-3 h-3 text-rose-400" />}
                              {insight.type === 'info' && <Info className="w-3 h-3 text-blue-400" />}
                              <span className="text-xs font-bold text-white">{insight.title}</span>
                          </div>
                          <p className="text-xs text-slate-400 leading-relaxed">{insight.description}</p>
                      </div>
                  ))}
              </div>

              {analysis.goal_proposals && analysis.goal_proposals.length > 0 && (
                  <div className="bg-slate-900 p-5 rounded-2xl border border-emerald-500/20">
                      <h4 className="text-emerald-400 text-[10px] font-bold uppercase tracking-widest mb-3 flex items-center gap-2"><Sparkles className="w-3 h-3" /> Opportunity</h4>
                      {analysis.goal_proposals.map((proposal) => (
                          <div key={proposal.id} className="space-y-3">
                              <div className="flex justify-between items-start">
                                  <div>
                                      <p className="text-sm font-bold text-white">{proposal.title}</p>
                                      <p className="text-[10px] text-slate-400 mt-1 max-w-xs">{proposal.reason_simple}</p>
                                  </div>
                                  <div className="text-right">
                                      <p className="text-sm font-bold text-emerald-400">{formatCurrency(proposal.target_amount)}</p>
                                      <p className="text-[8px] text-slate-500 font-bold uppercase tracking-wider">Target</p>
                                  </div>
                              </div>
                              <button onClick={() => handleAcceptProposal(proposal)} className="w-full py-2.5 bg-emerald-600 hover:bg-emerald-500 text-white font-bold rounded-lg text-[10px] uppercase tracking-widest shadow-lg shadow-emerald-900/20 transition-all flex items-center justify-center gap-2">
                                  <Check className="w-3 h-3" /> Accept Recommendation
                              </button>
                          </div>
                      ))}
                  </div>
              )}
          </div>
      );
  };

  return (
    <div className="h-[calc(100vh-8rem)] flex flex-col md:flex-row gap-6 overflow-hidden">
        {isLocked && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm">
                <div className="bg-slate-900 border border-white/10 p-8 rounded-3xl max-w-sm text-center shadow-2xl">
                    <div className="w-16 h-16 bg-gradient-to-tr from-indigo-500 to-purple-500 rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-lg">
                        <Lock className="w-8 h-8 text-white" />
                    </div>
                    <h3 className="text-xl font-bold text-white mb-2">Usage Limit Reached</h3>
                    <p className="text-slate-400 text-sm mb-6">You've used all {currentLimit} free AI analyses for this cycle. Upgrade to Elite for unlimited access.</p>
                    <button onClick={onUpgradeClick} className="w-full py-3 bg-white text-slate-900 font-bold rounded-xl hover:scale-105 transition-all">Upgrade Now</button>
                </div>
            </div>
        )}

        {/* Left Panel: Reports & Actions (Modernized) */}
        <div className="w-full md:w-1/3 flex flex-col gap-4 overflow-hidden">
            <div className="shrink-0 flex items-center justify-between mb-2">
                <h2 className="text-lg font-black text-white tracking-tight flex items-center gap-2">
                    <Bot className="w-5 h-5 text-indigo-500" /> Neural Coach
                </h2>
                <div className="px-2 py-0.5 bg-slate-800 rounded border border-white/5 text-[9px] font-bold text-slate-400">
                    {insightUsage} / {currentLimit} OPS
                </div>
            </div>

            <div className="grid grid-cols-3 gap-2 shrink-0">
                <button 
                    onClick={handleGenerateDaily}
                    className={`p-3 rounded-xl border transition-all text-center flex flex-col items-center justify-center gap-2 group ${activeView === 'daily' ? 'bg-white text-slate-900 border-white' : 'bg-slate-900/50 text-slate-400 border-white/5 hover:bg-slate-800 hover:text-white'}`}
                >
                    <Zap className={`w-4 h-4 ${activeView === 'daily' ? 'text-slate-900' : 'text-indigo-400'}`} />
                    <span className="text-[10px] font-bold uppercase tracking-wide">Daily</span>
                </button>
                <button 
                    onClick={handleGenerateMonthly}
                    className={`p-3 rounded-xl border transition-all text-center flex flex-col items-center justify-center gap-2 group ${activeView === 'monthly' ? 'bg-white text-slate-900 border-white' : 'bg-slate-900/50 text-slate-400 border-white/5 hover:bg-slate-800 hover:text-white'}`}
                >
                    <Calendar className={`w-4 h-4 ${activeView === 'monthly' ? 'text-slate-900' : 'text-amber-400'}`} />
                    <span className="text-[10px] font-bold uppercase tracking-wide">Monthly</span>
                </button>
                <button 
                    onClick={runAnalysis}
                    disabled={loading}
                    className={`p-3 rounded-xl border transition-all text-center flex flex-col items-center justify-center gap-2 group ${activeView === 'ai' ? 'bg-white text-slate-900 border-white' : 'bg-slate-900/50 text-slate-400 border-white/5 hover:bg-slate-800 hover:text-white'}`}
                >
                    {loading ? <RefreshCw className="w-4 h-4 animate-spin text-slate-900" /> : <BrainCircuit className={`w-4 h-4 ${activeView === 'ai' ? 'text-slate-900' : 'text-emerald-400'}`} />}
                    <span className="text-[10px] font-bold uppercase tracking-wide">AI Scan</span>
                </button>
            </div>

            <div className="flex-1 bg-slate-950/30 rounded-3xl border border-white/5 p-5 overflow-y-auto custom-scrollbar relative">
                {activeView === 'idle' && (
                    <div className="absolute inset-0 flex flex-col items-center justify-center text-center opacity-30 p-6">
                        <Activity className="w-12 h-12 text-slate-500 mb-3" />
                        <p className="text-xs font-bold text-slate-400">Select a protocol to initialize analysis.</p>
                    </div>
                )}
                {activeView === 'daily' && renderDailyReport()}
                {activeView === 'monthly' && renderMonthlyReport()}
                {activeView === 'ai' && renderAiAnalysis()}
            </div>
        </div>

        {/* Right Panel: Chat Interface (Modernized) */}
        <div className="flex-1 bg-[#0f172a] rounded-3xl border border-white/5 flex flex-col overflow-hidden relative shadow-2xl">
            {/* Chat Header */}
            <div className="p-4 border-b border-white/5 bg-slate-900/50 backdrop-blur-md flex justify-between items-center z-10">
                <div className="flex items-center gap-3">
                    <div className="w-8 h-8 bg-gradient-to-tr from-indigo-600 to-violet-600 rounded-lg flex items-center justify-center shadow-lg">
                        <MessageSquare className="w-4 h-4 text-white" />
                    </div>
                    <div>
                        <h3 className="font-bold text-white text-sm">Assistant</h3>
                        <div className="flex items-center gap-1.5">
                            <span className={`w-1.5 h-1.5 rounded-full ${botMode === 'ruthless' ? 'bg-rose-500' : 'bg-emerald-500'}`}></span>
                            <span className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">{botMode} Mode</span>
                        </div>
                    </div>
                </div>
                <button 
                    onClick={() => setChatHistory([])}
                    className="p-2 hover:bg-white/5 rounded-lg text-slate-500 hover:text-white transition-colors"
                    title="Clear Chat"
                >
                    <RefreshCcw className="w-4 h-4" />
                </button>
            </div>

            {/* Chat Messages Area */}
            <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar">
                {chatHistory.length === 0 && (
                    <div className="h-full flex flex-col items-center justify-center opacity-20">
                        <Bot className="w-16 h-16 text-slate-500 mb-4" />
                        <p className="text-sm font-bold text-slate-500">System Ready.</p>
                    </div>
                )}
                {chatHistory.map((msg) => (
                    <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} animate-slide-up group`}>
                        <div className={`max-w-[85%] md:max-w-[75%] p-4 rounded-2xl text-sm font-medium leading-relaxed shadow-sm relative ${
                            msg.role === 'user' 
                                ? 'bg-indigo-600 text-white rounded-br-sm' 
                                : 'bg-slate-800 text-slate-200 rounded-bl-sm border border-white/5'
                        }`}>
                            {msg.content}
                        </div>

                        {msg.suggestedActions && (
                            <div className="flex flex-wrap gap-2 mt-3 justify-start max-w-[90%]">
                                {msg.suggestedActions.map((action, idx) => (
                                    <button 
                                        key={idx} 
                                        onClick={() => handleActionClick(action)} 
                                        className="flex items-center gap-1.5 px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-indigo-300 hover:text-indigo-200 text-[10px] font-bold uppercase tracking-wider rounded-lg border border-white/5 transition-all shadow-sm"
                                    >
                                        {action.label} <ArrowUpRight className="w-3 h-3" />
                                    </button>
                                ))}
                            </div>
                        )}
                        <span className={`text-[9px] text-slate-600 font-bold mt-1.5 px-1 opacity-0 group-hover:opacity-100 transition-opacity`}>
                            {msg.timestamp.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}
                        </span>
                    </div>
                ))}
                {chatLoading && (
                    <div className="flex items-center gap-1 p-4 bg-slate-800/50 rounded-2xl rounded-bl-none w-fit border border-white/5">
                        <div className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce"></div>
                        <div className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce delay-100"></div>
                        <div className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce delay-200"></div>
                    </div>
                )}
                <div ref={chatEndRef} />
            </div>

            {/* Input Area */}
            <div className="p-4 bg-slate-900 border-t border-white/5 relative z-20">
                <form onSubmit={handleSendMessage} className="relative flex items-center gap-2">
                    <input 
                        type="text" 
                        value={chatInput} 
                        onChange={(e) => setChatInput(e.target.value)} 
                        placeholder="Type a command or query..." 
                        className="flex-1 bg-slate-950 border border-white/10 rounded-xl pl-4 pr-12 py-3.5 text-sm text-white focus:outline-none focus:border-indigo-500 transition-all placeholder:text-slate-600 font-medium"
                    />
                    <button 
                        type="submit" 
                        disabled={!chatInput.trim() || chatLoading} 
                        className="absolute right-2 top-1/2 -translate-y-1/2 p-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg transition-all disabled:opacity-50 shadow-lg active:scale-95"
                    >
                        <Send className="w-4 h-4" />
                    </button>
                </form>
            </div>
        </div>
    </div>
  );
};

export default Insights;

import React, { useState, useEffect, useRef } from 'react';
import { Transaction, AIAnalysisResponse, ChatMessage, UserPlan, TransactionType, Budget, BotMode, Category, Goal, FinancialSnapshot, SuggestedAction, GoalProposal, DailyReport, MonthlyReport, ReportType } from '../types';
import { analyzeFinancialData, chatWithFinancialCoach } from '../services/geminiService';
import { generateDailyReport, generateMonthlyReport } from '../services/reportEngine';
import { RefreshCcw, CheckCircle, AlertTriangle, ShieldAlert, Info, TrendingUp, Bot, BrainCircuit, Send, Lock, Sparkles, RefreshCw, Zap, Crown, Target, Calendar, Check, Activity, MessageSquare, ArrowUpRight, Flame, Utensils, ShoppingCart, Lightbulb, MoreHorizontal, Wallet, ShieldCheck, Brain, ChevronRight, X } from 'lucide-react';

interface InsightsProps {
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  userPlan: UserPlan;
  onUpgradeClick: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  initialPrompt?: string | null; 
  onPromptHandled?: () => void; 
  onApplyBudgets?: (budgets: Budget[]) => void; 
  insightUsage: number; 
  onIncrementUsage: () => void; 
  botMode: BotMode;
  onNavigate: (tab: string) => void;
  onAddGoal?: (goal: Goal) => void;
  autoScanTriggered?: boolean;
  activeReport?: ReportType;
  spendingLimit?: number;
}

const Insights: React.FC<InsightsProps> = ({ 
    transactions, 
    goals, 
    budgets, 
    userPlan, 
    onUpgradeClick, 
    formatCurrency, 
    initialPrompt, 
    onPromptHandled, 
    onApplyBudgets, 
    insightUsage, 
    onIncrementUsage, 
    botMode, 
    onNavigate, 
    onAddGoal,
    autoScanTriggered = false,
    activeReport,
    spendingLimit = 1000
}) => {
  const [analysis, setAnalysis] = useState<AIAnalysisResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([
    { 
        id: '1', 
        role: 'assistant', 
        content: botMode === 'ruthless' 
            ? 'I am connected. Auditing financial vectors. State your query or request a report.' 
            : 'Hello! I\'m here to help you optimize your financial wellness. How can I assist you today?', 
        timestamp: new Date(),
        sentiment: 'info'
    }
  ]);
  const [chatLoading, setChatLoading] = useState(false);

  // Dedicated Report State
  const [activeView, setActiveView] = useState<'idle' | 'daily' | 'monthly' | 'ai'>('idle');
  const [dailyReport, setDailyReport] = useState<DailyReport | null>(null);
  const [monthlyReport, setMonthlyReport] = useState<MonthlyReport | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);

  const isUltra = userPlan === 'ultra';
  const isPro = userPlan === 'pro';
  const currentLimit = isUltra ? 1500 : isPro ? 50 : 3;
  const isLocked = insightUsage >= currentLimit;

  // Handle activeReport trigger from external nav
  useEffect(() => {
      if (activeReport === 'daily') {
          handleGenerateDaily();
      } else if (activeReport === 'monthly') {
          handleGenerateMonthly();
      }
  }, [activeReport, transactions, spendingLimit]);

  // Initial Prompt Handler
  useEffect(() => {
      if (initialPrompt && onPromptHandled) {
          handleSendMessage(null, initialPrompt);
          onPromptHandled();
      }
  }, [initialPrompt]);

  const handleGenerateDaily = () => {
      const report = generateDailyReport(transactions, spendingLimit || 1000);
      setDailyReport(report);
      setActiveView('daily');
  };

  const handleGenerateMonthly = () => {
      const report = generateMonthlyReport(transactions, spendingLimit || 1000);
      setMonthlyReport(report);
      setActiveView('monthly');
  };

  const runAnalysis = async () => {
    if (isLocked || loading) return;
    setLoading(true);
    setError(null);
    onIncrementUsage();
    setActiveView('ai'); // Switch view immediately to show loading there

    try {
      const result = await analyzeFinancialData(transactions, userPlan);
      if (result) setAnalysis(result);
      else setError("Coach is analyzing other portfolios. Try again.");
    } catch (e) {
      setError("Unable to connect to financial brain.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (autoScanTriggered && !analysis && !loading && !isLocked) {
        runAnalysis();
    }
  }, [autoScanTriggered, analysis, loading, isLocked]);

  const handleAcceptProposal = (proposal: GoalProposal) => {
      if (proposal.type === 'goal' && onAddGoal) {
          onAddGoal({
              id: new Date().getTime().toString(),
              name: proposal.title,
              targetAmount: proposal.target_amount,
              currentAmount: 0,
              deadline: proposal.deadline || new Date(new Date().getTime() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
              icon: 'star',
              color: 'from-emerald-500 to-teal-500'
          });
      } else if (proposal.type === 'budget' && onApplyBudgets) {
          onApplyBudgets([{
              id: `ai_${new Date().getTime()}`,
              category: (proposal.category as Category) || Category.OTHER,
              limit: proposal.target_amount,
              startDate: new Date().toISOString()
          }]);
      }
      if (analysis) setAnalysis({ ...analysis, goal_proposals: analysis.goal_proposals.filter(p => p.id !== proposal.id) });
  };

  const handleSendMessage = async (e: React.FormEvent | null, promptOverride?: string) => {
    if (e) e.preventDefault();
    const content = promptOverride || chatInput;
    if (!content.trim() || isLocked) return;

    onIncrementUsage();
    const userMsg: ChatMessage = { id: new Date().getTime().toString(), role: 'user', content: content, timestamp: new Date() };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setChatLoading(true);

    const now = new Date();
    const currentMonthTxs = transactions.filter(t => new Date(t.date).getMonth() === now.getMonth());
    const income = currentMonthTxs.filter(t => t.type === TransactionType.INCOME).reduce((sum, t) => sum + t.amount, 0);
    const expense = currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).reduce((sum, t) => sum + t.amount, 0);

    const catMap: Record<string, number> = {};
    currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).forEach(t => { catMap[t.category] = (catMap[t.category] || 0) + t.amount; });
    const topCat = Object.entries(catMap).sort((a,b) => b[1] - a[1])[0];

    const snapshot: FinancialSnapshot = {
        currentMonthMetrics: {
            income,
            expense,
            savingsRate: income > 0 ? (income - expense) / income : 0,
            topExpenseCategory: topCat ? topCat[0] : 'None'
        },
        recentTransactions: transactions.slice(0, 10),
        activeGoals: goals,
        budgets: budgets
    };

    try {
        const response = await chatWithFinancialCoach(userMsg.content, chatHistory, snapshot, botMode, userPlan);
        setChatHistory(prev => [...prev, { 
            id: (new Date().getTime() + 1).toString(), 
            role: 'assistant', 
            content: response.message, 
            timestamp: new Date(),
            sentiment: response.sentiment as any,
            suggestedActions: response.suggestedActions
        }]);
    } catch (err) {
        setChatHistory(prev => [...prev, {
            id: (new Date().getTime() + 1).toString(),
            role: 'assistant',
            content: "I'm having trouble connecting to the analysis core right now. Please try again in a moment.",
            timestamp: new Date(),
            sentiment: 'critical'
        }]);
    } finally {
        setChatLoading(false);
    }
  };

  const handleActionClick = (action: SuggestedAction) => {
    if (action.actionId.startsWith('navigate_')) {
        const tab = action.actionId.replace('navigate_', '');
        onNavigate(tab);
    } else if (action.actionId === 'chat_prompt' && action.payload) {
        handleSendMessage(null, action.payload);
    }
  };

  useEffect(() => { chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [chatHistory, chatLoading]);

  // --- SUB-COMPONENTS ---

  const RiskGauge = ({ score }: { score: number }) => {
      const color = score >= 60 ? '#f43f5e' : score >= 30 ? '#f59e0b' : '#10b981';
      const safeScore = Number(score) || 0;
      const offset = 201 - (safeScore / 100) * 201;

      return (
          <div className="relative w-20 h-20 flex items-center justify-center">
              <svg className="w-full h-full transform -rotate-90">
                  <circle cx="40" cy="40" r="32" stroke="#1e293b" strokeWidth="6" fill="transparent" />
                  <circle cx="40" cy="40" r="32" stroke={color} strokeWidth="6" fill="transparent" strokeDasharray={201} strokeDashoffset={offset} strokeLinecap="round" />
              </svg>
              <div className="absolute flex flex-col items-center">
                  <span className="text-xl font-black text-white">{Math.round(safeScore)}</span>
                  <span className="text-[7px] font-bold uppercase tracking-widest text-slate-500">Risk</span>
              </div>
          </div>
      );
  };

  const HealthGauge = ({ score }: { score: number }) => {
      const color = score >= 80 ? '#10b981' : score >= 50 ? '#f59e0b' : '#f43f5e';
      const safeScore = Number(score) || 0;
      const offset = 201 - (safeScore / 100) * 201;

      return (
          <div className="relative w-20 h-20 flex items-center justify-center">
              <svg className="w-full h-full transform -rotate-90">
                  <circle cx="40" cy="40" r="32" stroke="#1e293b" strokeWidth="6" fill="transparent" />
                  <circle cx="40" cy="40" r="32" stroke={color} strokeWidth="6" fill="transparent" strokeDasharray={201} strokeDashoffset={offset} strokeLinecap="round" />
              </svg>
              <div className="absolute flex flex-col items-center">
                  <span className="text-xl font-black text-white">{Math.round(safeScore)}</span>
                  <span className="text-[7px] font-bold uppercase tracking-widest text-slate-500">Health</span>
              </div>
          </div>
      );
  };

  const renderDailyReport = () => {
      if (!dailyReport) return null;

      const percentUsed = Math.min(100, (dailyReport.totals.expense / dailyReport.totals.budget) * 100);
      const remaining = Math.max(0, dailyReport.totals.budget - dailyReport.totals.expense);

      // Top 3 Categories Logic
      const today = new Date(dailyReport.date);
      const todayTxs = transactions.filter(t => new Date(t.date).toDateString() === today.toDateString() && t.type === TransactionType.EXPENSE);
      const catMap = todayTxs.reduce((acc, t) => {
          const val = acc[t.category] || 0;
          return { ...acc, [t.category]: val + t.amount };
      }, {} as Record<string, number>);
      const topCats = Object.entries(catMap).sort((a,b) => b[1] - a[1]).slice(0, 3);

      return (
          <div className="font-sans text-slate-200 space-y-8 animate-slide-up pb-10">
              {/* Section 1: Narrative Gradient */}
              <section className="relative rounded-[2rem] p-8 md:p-12 overflow-hidden shadow-2xl shadow-indigo-500/20 text-white" style={{ background: 'linear-gradient(135deg, #4f46e5 0%, #312e81 100%)' }}>
                 <div className="absolute top-0 right-0 w-1/2 h-full opacity-10 pointer-events-none">
                    <svg className="w-full h-full transform translate-x-1/4 -translate-y-1/4 scale-150" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg">
                      <path d="M44.7,-76.4C58.1,-69.2,69.2,-58.1,77.3,-44.7C85.4,-31.3,90.5,-15.7,89.5,-0.6C88.5,14.5,81.4,29,71.9,41.4C62.4,53.8,50.5,64.1,37,71.4C23.5,78.7,8.4,83, -6.6,81.3C-21.6,79.5,-36.5,71.7,-49.2,61.4C-61.9,51.1,-72.4,38.3,-78.6,23.8C-84.8,9.3,-86.7,-6.9,-82.5,-21.8C-78.3,-36.7,-68,-50.3,-55.1,-58.1C-42.2,-65.9,-26.7,-67.9,-12.3,-74.8C2.1,-81.7,16.4,-93.5,31.3,-83.6C44.7,-76.4,44.7,-76.4,44.7,-76.4Z" fill="#FFFFFF" transform="translate(100 100)"></path>
                    </svg>
                 </div>

                 <div className="relative z-10 max-w-3xl">
                    <div className="flex items-center gap-3 mb-6">
                      <span className="px-3 py-1 bg-white/20 backdrop-blur-md rounded-full text-[10px] font-bold tracking-widest uppercase">Daily Narrative</span>
                      <span className="text-white/60 text-xs italic font-medium">— {new Date(dailyReport.date).toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' })}</span>
                    </div>
                    <h2 className="text-2xl md:text-3xl font-light leading-snug">
                      Hello, Pilot. You are <span className={`font-bold ${dailyReport.riskLevel === 'Critical' ? 'text-rose-300' : 'text-emerald-300'}`}>{dailyReport.riskLevel === 'Stable' ? 'perfectly on track' : dailyReport.riskLevel}</span> today. 
