                            {loading ? <RefreshCw className="w-4 h-4 animate-spin text-slate-900" /> : <BrainCircuit className={`w-4 h-4 ${activeView === 'ai' ? 'text-slate-900' : 'text-emerald-400'}`} />}
                            <span className="text-[10px] font-bold uppercase tracking-wide">AI Scan</span>
                        </button>
                    </div>
                </>
            ) : (
                <div className="shrink-0 flex items-center justify-between mb-2 p-2 bg-slate-900/50 rounded-2xl border border-white/5 backdrop-blur-md animate-fade-in">
                    <div className="flex items-center gap-3 px-2">
                        <div className={`p-2 rounded-xl ${activeView === 'daily' ? 'bg-indigo-500/20 text-indigo-400' : 'bg-amber-500/20 text-amber-400'}`}>
                            {activeView === 'daily' ? <Zap className="w-5 h-5" /> : <Calendar className="w-5 h-5" />}
                        </div>
                        <h2 className="text-lg font-bold text-white tracking-tight">
                            {activeView === 'daily' ? 'Daily Analysis' : 'Monthly Audit'}
                        </h2>
                    </div>
                    <button 
                        onClick={closeReport}
                        className="p-2 hover:bg-white/10 rounded-xl text-slate-400 hover:text-white transition-colors"
                    >
                        <X className="w-6 h-6" />
                    </button>
                </div>
            )}

            <div className={`flex-1 bg-slate-950/30 rounded-3xl border border-white/5 p-5 overflow-y-auto custom-scrollbar relative ${isFocusMode ? 'shadow-2xl bg-slate-900/20' : ''}`}>
                {activeView === 'idle' && (
                    <div className="absolute inset-0 flex flex-col items-center justify-center text-center opacity-30 p-6">
                        <Activity className="w-12 h-12 text-slate-500 mb-3" />
                        <p className="text-xs font-bold text-slate-400">Select a protocol to initialize analysis.</p>
                    </div>
                )}
                {activeView === 'daily' && renderDailyReport()}
                {activeView === 'monthly' && renderMonthlyReport()}
                {activeView === 'ai' && renderAiAnalysis()}
            </div>
        </div>

        {/* Right Panel: Chat Interface (Compacted & Adjusted Ratio) */}
        {!isFocusMode && (
            <div className="flex-1 bg-[#0f172a] rounded-3xl border border-white/5 flex flex-col overflow-hidden relative shadow-2xl animate-fade-in">
                {/* Chat Header (Fixed Height) */}
                <div className="h-14 px-4 border-b border-white/5 bg-slate-900/50 backdrop-blur-md flex justify-between items-center z-10 shrink-0">
                    <div className="flex items-center gap-3">
                        <div className="w-7 h-7 bg-gradient-to-tr from-indigo-600 to-violet-600 rounded-lg flex items-center justify-center shadow-lg">
                            <MessageSquare className="w-3.5 h-3.5 text-white" />
                        </div>
                        <div>
                            <h3 className="font-bold text-white text-sm leading-none">Assistant</h3>
                            <div className="flex items-center gap-1.5 mt-0.5">
                                <span className={`w-1.5 h-1.5 rounded-full ${botMode === 'ruthless' ? 'bg-rose-500' : 'bg-emerald-500'}`}></span>
                                <span className="text-[9px] font-bold text-slate-500 uppercase tracking-wider leading-none">{botMode} Mode</span>
                            </div>
                        </div>
                    </div>
                    <button 
                        onClick={() => setChatHistory([])}
                        className="p-1.5 hover:bg-white/5 rounded-lg text-slate-500 hover:text-white transition-colors"
                        title="Clear Chat"
                    >
                        <RefreshCcw className="w-3.5 h-3.5" />
                    </button>
                </div>

                {/* Chat Messages Area */}
                <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar">
                    {chatHistory.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center opacity-20">
                            <Bot className="w-12 h-12 text-slate-500 mb-4" />
                            <p className="text-xs font-bold text-slate-500 uppercase tracking-widest">System Ready.</p>
                        </div>
                    )}
                    {chatHistory.map((msg) => (
                        <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} animate-slide-up group`}>
                            <div className={`max-w-[90%] md:max-w-[80%] py-2.5 px-3.5 rounded-2xl text-sm font-medium leading-relaxed shadow-sm relative ${
                                msg.role === 'user' 
                                    ? 'bg-indigo-600 text-white rounded-br-sm' 
                                    : 'bg-slate-800 text-slate-200 rounded-bl-sm border border-white/5'
                            }`}>
                                {msg.content}
                            </div>

                            {msg.suggestedActions && (
                                <div className="flex flex-wrap gap-2 mt-2 justify-start max-w-[90%]">
                                    {msg.suggestedActions.map((action, idx) => (
                                        <button 
                                            key={idx} 
                                            onClick={() => handleActionClick(action)} 
                                            className="flex items-center gap-1.5 px-2.5 py-1 bg-slate-800 hover:bg-slate-700 text-indigo-300 hover:text-indigo-200 text-[9px] font-bold uppercase tracking-wider rounded-lg border border-white/5 transition-all shadow-sm"
                                        >
                                            {action.label} <ArrowUpRight className="w-2.5 h-2.5" />
                                        </button>
                                    ))}
                                </div>
                            )}
                            <span className={`text-[8px] text-slate-600 font-bold mt-1 px-1 opacity-0 group-hover:opacity-100 transition-opacity`}>
                                {msg.timestamp.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}
                            </span>
                        </div>
                    ))}
                    {chatLoading && (
                        <div className="flex items-center gap-1 py-3 px-4 bg-slate-800/50 rounded-2xl rounded-bl-none w-fit border border-white/5">
                            <div className="w-1 h-1 bg-slate-500 rounded-full animate-bounce"></div>
                            <div className="w-1 h-1 bg-slate-500 rounded-full animate-bounce delay-100"></div>
                            <div className="w-1 h-1 bg-slate-500 rounded-full animate-bounce delay-200"></div>
                        </div>
                    )}
                    <div ref={chatEndRef} />
                </div>

                {/* Input Area */}
                <div className="p-3 bg-slate-900 border-t border-white/5 relative z-20 shrink-0">
                    <form onSubmit={handleSendMessage} className="relative flex items-center gap-2">
                        <input 
                            type="text" 
                            value={chatInput} 
                            onChange={(e) => setChatInput(e.target.value)} 
                            placeholder="Type a command or query..." 
                            className="flex-1 bg-slate-950 border border-white/10 rounded-xl pl-4 pr-10 py-3 text-xs text-white focus:outline-none focus:border-indigo-500 transition-all placeholder:text-slate-600 font-medium"
                        />
                        <button 
                            type="submit" 
                            disabled={!chatInput.trim() || chatLoading} 
                            className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg transition-all disabled:opacity-50 shadow-lg active:scale-95"
                        >
                            <Send className="w-3.5 h-3.5" />
                        </button>
                    </form>
                </div>
            </div>
        )}
    </div>
  );
};

export default Insights;

