import { Transaction, AIAnalysisResponse, ChatMessage, UserPlan, TransactionType, Budget, BotMode, Category, Goal, FinancialSnapshot, SuggestedAction, GoalProposal, DailyReport, MonthlyReport, ReportType } from '../types';
import { analyzeFinancialData, chatWithFinancialCoach } from '../services/geminiService';
import { generateDailyReport, generateMonthlyReport } from '../services/reportEngine';
import { RefreshCcw, CheckCircle, AlertTriangle, ShieldAlert, Info, TrendingUp, Bot, BrainCircuit, Send, Lock, Sparkles, RefreshCw, Zap, Crown, Target, Calendar, Check, Activity, MessageSquare, ArrowUpRight, Flame, Utensils, ShoppingCart, Lightbulb, MoreHorizontal, Wallet, ShieldCheck, Brain, ChevronRight, X } from 'lucide-react';

interface InsightsProps {
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  userPlan: UserPlan;
  onUpgradeClick: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  initialPrompt?: string | null; 
  onPromptHandled?: () => void; 
  onApplyBudgets?: (budgets: Budget[]) => void; 
  insightUsage: number; 
  onIncrementUsage: () => void; 
  botMode: BotMode;
  onNavigate: (tab: string) => void;
  onAddGoal?: (goal: Goal) => void;
  autoScanTriggered?: boolean;
  activeReport?: ReportType;
  spendingLimit?: number;
}

const Insights: React.FC<InsightsProps> = ({ 
    transactions, 
    goals, 
    budgets, 
    userPlan, 
    onUpgradeClick, 
    formatCurrency, 
    initialPrompt, 
    onPromptHandled, 
    onApplyBudgets, 
    insightUsage, 
    onIncrementUsage, 
    botMode, 
    onNavigate, 
    onAddGoal,
    autoScanTriggered = false,
    activeReport,
    spendingLimit = 1000
}) => {
  const [analysis, setAnalysis] = useState<AIAnalysisResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([
    { 
        id: '1', 
        role: 'assistant', 
        content: botMode === 'ruthless' 
            ? 'I am connected. Auditing financial vectors. State your query or request a report.' 
            : 'Hello! I\'m here to help you optimize your financial wellness. How can I assist you today?', 
        timestamp: new Date(),
        sentiment: 'info'
    }
  ]);
  const [chatLoading, setChatLoading] = useState(false);

  // Dedicated Report State
  const [activeView, setActiveView] = useState<'idle' | 'daily' | 'monthly' | 'ai'>('idle');
  const [dailyReport, setDailyReport] = useState<DailyReport | null>(null);
  const [monthlyReport, setMonthlyReport] = useState<MonthlyReport | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);

  const isUltra = userPlan === 'ultra';
  const isPro = userPlan === 'pro';
  const currentLimit = isUltra ? 1500 : isPro ? 50 : 3;
  const isLocked = insightUsage >= currentLimit;

  // Focus Mode Logic: Full screen for Daily and Monthly reports
  const isFocusMode = activeView === 'daily' || activeView === 'monthly';

  // Handle activeReport trigger from external nav
  useEffect(() => {
      if (activeReport === 'daily') {
          handleGenerateDaily();
      } else if (activeReport === 'monthly') {
          handleGenerateMonthly();
      }
  }, [activeReport, transactions, spendingLimit]);

  // Initial Prompt Handler
  useEffect(() => {
      if (initialPrompt && onPromptHandled) {
          handleSendMessage(null, initialPrompt);
          onPromptHandled();
      }
  }, [initialPrompt]);

  const handleGenerateDaily = () => {
      const report = generateDailyReport(transactions, spendingLimit || 1000);
      setDailyReport(report);
      setActiveView('daily');
  };

  const handleGenerateMonthly = () => {
      const report = generateMonthlyReport(transactions, spendingLimit || 1000);
      setMonthlyReport(report);
      setActiveView('monthly');
  };

  const closeReport = () => {
      setActiveView('idle');
  };

  const runAnalysis = async () => {
    if (isLocked || loading) return;
    setLoading(true);
    setError(null);
    onIncrementUsage();
    setActiveView('ai'); // Switch view immediately to show loading there

    try {
      const result = await analyzeFinancialData(transactions, userPlan);
      if (result) setAnalysis(result);
      else setError("Coach is analyzing other portfolios. Try again.");
    } catch (e) {
      setError("Unable to connect to financial brain.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (autoScanTriggered && !analysis && !loading && !isLocked) {
        runAnalysis();
    }
  }, [autoScanTriggered, analysis, loading, isLocked]);

  const handleAcceptProposal = (proposal: GoalProposal) => {
      if (proposal.type === 'goal' && onAddGoal) {
          onAddGoal({
              id: new Date().getTime().toString(),
              name: proposal.title,
              targetAmount: proposal.target_amount,
              currentAmount: 0,
              deadline: proposal.deadline || new Date(new Date().getTime() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
              icon: 'star',
              color: 'from-emerald-500 to-teal-500'
          });
      } else if (proposal.type === 'budget' && onApplyBudgets) {
          onApplyBudgets([{
              id: `ai_${new Date().getTime()}`,
              category: (proposal.category as Category) || Category.OTHER,
              limit: proposal.target_amount,
              startDate: new Date().toISOString()
          }]);
      }
      if (analysis) setAnalysis({ ...analysis, goal_proposals: analysis.goal_proposals.filter(p => p.id !== proposal.id) });
  };

  const handleSendMessage = async (e: React.FormEvent | null, promptOverride?: string) => {
    if (e) e.preventDefault();
    const content = promptOverride || chatInput;
    if (!content.trim() || isLocked) return;

    onIncrementUsage();
    // Using Date.now() for consistency and reliability
    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', content: content, timestamp: new Date() };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setChatLoading(true);

    const now = new Date();
    const currentMonthTxs = transactions.filter(t => new Date(t.date).getMonth() === now.getMonth());
    const income = currentMonthTxs.filter(t => t.type === TransactionType.INCOME).reduce((sum, t) => sum + t.amount, 0);
    const expense = currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).reduce((sum, t) => sum + t.amount, 0);

    const catMap: Record<string, number> = {};
    currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).forEach(t => { catMap[t.category] = (catMap[t.category] || 0) + t.amount; });
    const topCat = Object.entries(catMap).sort((a,b) => b[1] - a[1])[0];

    const snapshot: FinancialSnapshot = {
        currentMonthMetrics: {
            income,
            expense,
            savingsRate: income > 0 ? (income - expense) / income : 0,
            topExpenseCategory: topCat ? topCat[0] : 'None'
        },
        recentTransactions: transactions.slice(0, 10),
        activeGoals: goals,
        budgets: budgets
    };

    try {
        const response = await chatWithFinancialCoach(userMsg.content, chatHistory, snapshot, botMode, userPlan);
        setChatHistory(prev => [...prev, { 
            id: (Date.now() + 1).toString(), 
            role: 'assistant', 
            content: response.message, 
            timestamp: new Date(),
            sentiment: response.sentiment as any,
            suggestedActions: response.suggestedActions
        }]);
    } catch (err) {
        setChatHistory(prev => [...prev, {
            id: (Date.now() + 1).toString(),
            role: 'assistant',
            content: "I'm having trouble connecting to the analysis core right now. Please try again in a moment.",
            timestamp: new Date(),
            sentiment: 'critical'
        }]);
    } finally {
        setChatLoading(false);
    }
  };

  const handleActionClick = (action: SuggestedAction) => {
    if (action.actionId.startsWith('navigate_')) {
        const tab = action.actionId.replace('navigate_', '');
        onNavigate(tab);
    } else if (action.actionId === 'chat_prompt' && action.payload) {
        handleSendMessage(null, action.payload);
    }
  };

  useEffect(() => { chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [chatHistory, chatLoading]);

  // --- SUB-COMPONENTS ---

  const RiskGauge = ({ score }: { score: number }) => {
      const safeScore = typeof score === 'number' && !isNaN(score) ? score : 0;
      const color = safeScore >= 60 ? '#f43f5e' : safeScore >= 30 ? '#f59e0b' : '#10b981';
      const offset = 201 - (safeScore / 100) * 201;

      return (
          <div className="relative w-20 h-20 flex items-center justify-center">
              <svg className="w-full h-full transform -rotate-90">
                  <circle cx="40" cy="40" r="32" stroke="#1e293b" strokeWidth="6" fill="transparent" />
                  <circle cx="40" cy="40" r="32" stroke={color} strokeWidth="6" fill="transparent" strokeDasharray={201} strokeDashoffset={offset} strokeLinecap="round" />
              </svg>
              <div className="absolute flex flex-col items-center">
                  <span className="text-xl font-black text-white">{Math.round(safeScore)}</span>
                  <span className="text-[7px] font-bold uppercase tracking-widest text-slate-500">Risk</span>
              </div>
          </div>
      );
  };

  const HealthGauge = ({ score }: { score: number }) => {
      const safeScore = typeof score === 'number' && !isNaN(score) ? score : 0;
      const color = safeScore >= 80 ? '#10b981' : safeScore >= 50 ? '#f59e0b' : '#f43f5e';
      const offset = 201 - (safeScore / 100) * 201;

      return (
          <div className="relative w-20 h-20 flex items-center justify-center">
              <svg className="w-full h-full transform -rotate-90">
                  <circle cx="40" cy="40" r="32" stroke="#1e293b" strokeWidth="6" fill="transparent" />
                  <circle cx="40" cy="40" r="32" stroke={color} strokeWidth="6" fill="transparent" strokeDasharray={201} strokeDashoffset={offset} strokeLinecap="round" />
              </svg>
              <div className="absolute flex flex-col items-center">
                  <span className="text-xl font-black text-white">{Math.round(safeScore)}</span>
                  <span className="text-[7px] font-bold uppercase tracking-widest text-slate-500">Health</span>
              </div>
          </div>
      );
  };

  const renderDailyReport = () => {
      if (!dailyReport) return null;

      const percentUsed = Math.min(100, (dailyReport.totals.expense / dailyReport.totals.budget) * 100);
      const remaining = Math.max(0, dailyReport.totals.budget - dailyReport.totals.expense);

      // Top 3 Categories Logic
      const today = new Date(dailyReport.date);
      const todayTxs = transactions.filter(t => new Date(t.date).toDateString() === today.toDateString() && t.type === TransactionType.EXPENSE);
      const catMap = todayTxs.reduce((acc, t) => {
          const val = acc[t.category] || 0;
          return { ...acc, [t.category]: val + t.amount };
      }, {} as Record<string, number>);
      const topCats = Object.entries(catMap).sort((a,b) => b[1] - a[1]).slice(0, 3);

      return (
          <div className="font-sans text-slate-200 space-y-8 animate-slide-up pb-10">
              {/* Section 1: Narrative Gradient */}
              <section className="relative rounded-[2rem] p-8 md:p-12 overflow-hidden shadow-2xl shadow-indigo-500/20 text-white" style={{ background: 'linear-gradient(135deg, #4f46e5 0%, #312e81 100%)' }}>
                 <div className="absolute top-0 right-0 w-1/2 h-full opacity-10 pointer-events-none">
                    <svg className="w-full h-full transform translate-x-1/4 -translate-y-1/4 scale-150" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg">
                      <path d="M44.7,-76.4C58.1,-69.2,69.2,-58.1,77.3,-44.7C85.4,-31.3,90.5,-15.7,89.5,-0.6C88.5,14.5,81.4,29,71.9,41.4C62.4,53.8,50.5,64.1,37,71.4C23.5,78.7,8.4,83, -6.6,81.3C-21.6,79.5,-36.5,71.7,-49.2,61.4C-61.9,51.1,-72.4,38.3,-78.6,23.8C-84.8,9.3,-86.7,-6.9,-82.5,-21.8C-78.3,-36.7,-68,-50.3,-55.1,-58.1C-42.2,-65.9,-26.7,-67.9,-12.3,-74.8C2.1,-81.7,16.4,-93.5,31.3,-83.6C44.7,-76.4,44.7,-76.4,44.7,-76.4Z" fill="#FFFFFF" transform="translate(100 100)"></path>
                    </svg>
                 </div>

                 <div className="relative z-10 max-w-3xl">
                    <div className="flex items-center gap-3 mb-6">
                      <span className="px-3 py-1 bg-white/20 backdrop-blur-md rounded-full text-[10px] font-bold tracking-widest uppercase">Daily Narrative</span>
                      <span className="text-white/60 text-xs italic font-medium">— {new Date(dailyReport.date).toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' })}</span>
                    </div>
                    <h2 className="text-2xl md:text-3xl font-light leading-snug">
                      Hello, Pilot. You are <span className={`font-bold ${dailyReport.riskLevel === 'Critical' ? 'text-rose-300' : 'text-emerald-300'}`}>{dailyReport.riskLevel === 'Stable' ? 'perfectly on track' : dailyReport.riskLevel}</span> today. 
                      Spending is <span className="font-bold">{formatCurrency(dailyReport.totals.expense)}</span>. You have <span className="font-bold">{formatCurrency(remaining)}</span> remaining in your daily capacity.
                    </h2>
                    <div className="mt-8 flex flex-wrap gap-4">
                      <div className="flex items-center gap-2 text-xs font-bold text-white/80 bg-black/20 px-3 py-1.5 rounded-lg">
                         <CheckCircle className="w-4 h-4 text-emerald-300" />
                         <span>System Nominal</span>
                      </div>
                      <div className="flex items-center gap-2 text-xs font-bold text-white/80 bg-black/20 px-3 py-1.5 rounded-lg">
                         <ShieldCheck className="w-4 h-4 text-indigo-300" />
                         <span>Risk Score: {dailyReport.riskScore}</span>
                      </div>
                    </div>
                 </div>
              </section>

              {/* Section 2: Grid */}
              <section className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  {/* Card 1: Budget Status */}
                  <div className="bg-slate-900/50 p-6 rounded-[2rem] border border-white/5 shadow-lg">
                      <div className="flex items-center justify-between mb-6">
                          <h3 className="font-black text-slate-500 text-[10px] uppercase tracking-widest">Daily Capacity</h3>
                          <Wallet className="text-indigo-500 w-5 h-5" />
                      </div>
                      <div className="space-y-4">
                          <div className="flex justify-between items-end">
                              <span className="text-2xl font-black text-white">{formatCurrency(dailyReport.totals.expense)}</span>
                              <span className="text-xs font-bold text-slate-500">of {formatCurrency(dailyReport.totals.budget)}</span>
                          </div>
                          <div className="w-full h-2 bg-slate-800 rounded-full overflow-hidden">
                              <div className={`h-full rounded-full ${percentUsed > 100 ? 'bg-rose-500' : 'bg-indigo-500'}`} style={{ width: `${Math.min(percentUsed, 100)}%` }}></div>
                          </div>
                          <p className="text-xs text-slate-400 leading-relaxed font-medium">
                              You have used <span className="text-white font-bold">{percentUsed.toFixed(0)}%</span> of your daily allocation.
                          </p>
                      </div>
                  </div>

                  {/* Card 2: Streak */}
                  <div className="bg-slate-900/50 p-6 rounded-[2rem] border border-white/5 shadow-lg">
                      <div className="flex items-center justify-between mb-6">
                          <h3 className="font-black text-slate-500 text-[10px] uppercase tracking-widest">Momentum</h3>
                          <Flame className="text-orange-500 w-5 h-5" />
                      </div>
                      <div className="flex items-center gap-4">
                          <div className="text-3xl font-black text-white">{(dailyReport.metrics.momentumDelta * 100).toFixed(0)}%</div>
                          <div className="text-xs">
                              <p className="font-bold text-slate-300">Variance</p>
                              <p className="text-slate-500">vs 7-Day Avg</p>
                          </div>
                      </div>
                      <div className="flex gap-1.5 mt-6">
                          {[...Array(7)].map((_, i) => (
                              <div key={i} className={`flex-1 h-6 rounded ${i < 5 ? 'bg-orange-500/20' : 'bg-slate-800'} ${i === 4 ? 'bg-orange-500' : ''}`}></div>
                          ))}
                      </div>
                  </div>

                  {/* Card 3: Top Categories */}
                  <div className="bg-slate-900/50 p-6 rounded-[2rem] border border-white/5 shadow-lg">
                      <div className="flex items-center justify-between mb-6">
                          <h3 className="font-black text-slate-500 text-[10px] uppercase tracking-widest">Today's Activity</h3>
                          <MoreHorizontal className="text-slate-500 w-5 h-5" />
                      </div>
                      <div className="space-y-3">
                          {topCats.length > 0 ? topCats.map(([cat, amt]) => (
                              <div key={cat} className="flex items-center justify-between p-2 rounded-lg hover:bg-white/5 transition-colors">
                                  <div className="flex items-center gap-3">
                                      {cat === 'Food & Dining' ? <Utensils className="w-4 h-4 text-blue-400" /> : 
                                       cat === 'Shopping' ? <ShoppingCart className="w-4 h-4 text-purple-400" /> : 
                                       <Zap className="w-4 h-4 text-emerald-400" />}
                                      <span className="text-xs font-bold text-slate-300">{cat}</span>
                                  </div>
                                  <span className="text-xs font-black text-white">{formatCurrency(amt)}</span>
                              </div>
                          )) : (
                              <div className="text-xs text-slate-500 text-center py-4">No activity recorded today.</div>
                          )}
                      </div>
                  </div>
              </section>

              {/* Section 3: Deep Dive */}
              <section className="bg-slate-900 border border-white/5 rounded-[2.5rem] shadow-xl overflow-hidden grid grid-cols-1 lg:grid-cols-2">
                  <div className="p-10 space-y-8">
                      <div className="flex items-center gap-2 mb-2">
                          <Brain className="w-5 h-5 text-indigo-400" />
                          <h3 className="text-lg font-black text-white tracking-tight uppercase">Coach's Deep Dive</h3>
                      </div>
                      <div className="space-y-6">
                          <h4 className="text-xl font-bold text-white leading-tight">{dailyReport.signals[0]?.title || 'System Check'}</h4>
                          <p className="text-slate-400 text-sm leading-relaxed font-medium">
                              {dailyReport.signals[0]?.description || dailyReport.action.text} 
                              <span className="block mt-2 text-slate-300">{dailyReport.action.effect}</span>
                          </p>
                          <div className="bg-indigo-500/10 p-5 rounded-2xl border border-indigo-500/20">
                              <div className="flex gap-4">
                                  <Lightbulb className="w-5 h-5 text-indigo-400 shrink-0 mt-0.5" />
                                  <div className="space-y-1">
                                      <p className="font-bold text-xs text-indigo-200 uppercase tracking-wider">Actionable Strategy</p>
                                      <p className="text-xs text-slate-300 font-medium leading-relaxed">{dailyReport.action.text}</p>
                                  </div>
                              </div>
                          </div>
                      </div>
                      <div className="flex flex-wrap gap-4 pt-2">
                          <button className="px-6 py-3 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-xl text-xs uppercase tracking-widest shadow-lg shadow-indigo-500/20 flex items-center gap-2 transition-all">
                              <Utensils className="w-4 h-4" /> Set Limit
                          </button>
                          <button className="px-6 py-3 bg-slate-800 hover:bg-slate-700 text-slate-300 font-bold rounded-xl text-xs uppercase tracking-widest border border-white/5 flex items-center gap-2 transition-all">
                              <Calendar className="w-4 h-4" /> Remind Me
                          </button>
                      </div>
                  </div>

                  <div className="bg-indigo-950/20 p-10 flex flex-col justify-center border-l border-white/5 relative">
                      <div className="space-y-8 relative z-10">
                          <div>
                              <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-6">Projected Savings Impact</p>
                              <div className="relative h-40 flex items-end gap-3 px-4">
                                  {/* Mock Bars based on HTML structure but adapted */}
                                  <div className="flex-1 bg-indigo-500/20 rounded-t-lg h-[40%]"></div>
                                  <div className="flex-1 bg-indigo-500/30 rounded-t-lg h-[55%]"></div>
                                  <div className="flex-1 bg-indigo-500/40 rounded-t-lg h-[45%]"></div>
                                  <div className="flex-1 bg-indigo-500 rounded-t-lg h-[85%] relative shadow-[0_0_15px_rgba(99,102,241,0.4)] group">
                                      <div className="absolute -top-8 left-1/2 -translate-x-1/2 text-xs font-black text-white animate-bounce">{formatCurrency(remaining)}</div>
                                      <div className="absolute -bottom-6 left-1/2 -translate-x-1/2 text-[9px] font-bold text-slate-400 uppercase whitespace-nowrap">This Week</div>
                                  </div>
                                  <div className="flex-1 bg-indigo-500/20 rounded-t-lg h-[35%]"></div>
                                  <div className="flex-1 bg-indigo-500/20 rounded-t-lg h-[50%]"></div>
                              </div>
                          </div>
                          <div className="grid grid-cols-2 gap-4">
                              <div className="bg-slate-900/50 p-4 rounded-xl border border-white/5">
                                  <p className="text-[9px] font-bold text-slate-500 uppercase">Success Rate</p>
                                  <p className="text-xl font-black text-white">94%</p>
                              </div>
                              <div className="bg-slate-900/50 p-4 rounded-xl border border-white/5">
                                  <p className="text-[9px] font-bold text-slate-500 uppercase">Impact Score</p>
                                  <p className="text-xl font-black text-emerald-400">High</p>
                              </div>
                          </div>
                      </div>
                  </div>
              </section>

              <footer className="text-center pt-4 pb-8 opacity-40">
                  <p className="text-[9px] font-bold text-slate-500 uppercase tracking-[0.2em]">Data synced 2 minutes ago • Neural Engine V3</p>
              </footer>
          </div>
      );
  };

  const renderMonthlyReport = () => {
      if (!monthlyReport) return null;
      return (
          <div className="space-y-6 animate-slide-up pb-6">
              <div className="flex items-center justify-between">
                  <div>
                      <h3 className="text-xl font-bold text-white mb-1">Monthly Audit</h3>
                      <p className="text-slate-400 text-xs">{monthlyReport.month}</p>
                  </div>
                  <HealthGauge score={monthlyReport.healthScore} />
              </div>

              <div className="grid grid-cols-3 gap-2">
                  <div className="p-3 bg-slate-900 rounded-xl border border-white/5 text-center">
                      <p className="text-slate-500 text-[8px] font-bold uppercase tracking-wider mb-1">Savings Rate</p>
                      <p className={`text-base font-black ${monthlyReport.metrics.savingsPowerIndex > 0.1 ? 'text-emerald-400' : 'text-rose-400'}`}>{(monthlyReport.metrics.savingsPowerIndex * 100).toFixed(0)}%</p>
                  </div>
                  <div className="p-3 bg-slate-900 rounded-xl border border-white/5 text-center">
                      <p className="text-slate-500 text-[8px] font-bold uppercase tracking-wider mb-1">Fixed Load</p>
                      <p className="text-base font-black text-white">{(monthlyReport.metrics.expenseLoadRatio * 100).toFixed(0)}%</p>
                  </div>
                  <div className="p-3 bg-slate-900 rounded-xl border border-white/5 text-center">
                      <p className="text-slate-500 text-[8px] font-bold uppercase tracking-wider mb-1">Risk Factor</p>
                      <p className={`text-base font-black ${monthlyReport.riskScore > 50 ? 'text-rose-400' : 'text-emerald-400'}`}>{monthlyReport.riskScore.toFixed(0)}</p>
                  </div>
              </div>

              <div className="bg-slate-900 p-5 rounded-2xl border border-indigo-500/20 relative overflow-hidden">
                  <div className="absolute top-0 right-0 p-4 opacity-5"><Crown className="w-16 h-16" /></div>
                  <h4 className="text-indigo-400 text-[10px] font-bold uppercase tracking-widest mb-2 flex items-center gap-2"><Sparkles className="w-3 h-3" /> Strategic Objective</h4>
                  <p className="text-base font-bold text-white mb-3 leading-tight">{monthlyReport.strategicPlan.objective}</p>
                  <ul className="space-y-2">
                      {monthlyReport.strategicPlan.actions.map((act, i) => (
