                      } 
                  } 
              },
              predicted_spend_next_month: { type: Type.NUMBER },
              risk_score: { type: Type.NUMBER }
            }
          }
        }
      });

      if (response.text) {
        return JSON.parse(cleanJsonResponse(response.text)) as AIAnalysisResponse;
      }
      return null;
    } catch (error) {
      console.error("AI Analysis Failed", error);
      throw error; // Re-throw to trigger fallback if applicable
    }
  });
};

export const generateDailyInsight = async (transactions: Transaction[], spendingLimit: number, userPlan: UserPlan = 'free'): Promise<DailyReport> => {
    // 1. Calculate Deterministic Math locally (Speed + Accuracy)
    const today = new Date();
    const todayStr = today.toDateString();

    // Filter for today's expenses
    const todayTxs = transactions.filter(t => 
        new Date(t.date).toDateString() === todayStr && 
        t.type === TransactionType.EXPENSE
    );
    const spentToday = todayTxs.reduce((sum, t) => sum + t.amount, 0);

    // Daily Cap (Monthly Limit / 30)
    const dailyCap = Math.max(1, spendingLimit / 30);
    const safeRemaining = Math.max(0, dailyCap - spentToday);

    // Month Projection
    const currentMonthTxs = transactions.filter(t =>
        t.type === TransactionType.EXPENSE &&
        new Date(t.date).getMonth() === today.getMonth() &&
        new Date(t.date).getFullYear() === today.getFullYear()
    );
    const monthSpent = currentMonthTxs.reduce((sum, t) => sum + t.amount, 0);
    const dayOfMonth = today.getDate();
    const daysInMonth = new Date(today.getFullYear(), today.getMonth() + 1, 0).getDate();

    // Simple Linear Projection
    const projectedSpend = dayOfMonth > 0 ? (monthSpent / dayOfMonth) * daysInMonth : 0;
    const isProjectedOver = projectedSpend > spendingLimit;
    const deltaPercent = spendingLimit > 0 ? ((projectedSpend - spendingLimit) / spendingLimit) * 100 : 0;

    // Prepare Data for AI
    const context = {
        spentToday,
        dailyCap,
        safeRemaining,
        monthSpent,
        monthLimit: spendingLimit,
        projectedSpend,
        recentTxs: todayTxs.map(t => `${t.merchant} ($${t.amount})`).join(', ')
    };

    return withGeminiRetry(userPlan, async (ai) => {
        try {
            const response = await ai.models.generateContent({
                model: "gemini-3-flash-preview",
                contents: `
                    Analyze this daily financial snapshot.
                    Context: ${JSON.stringify(context)}

                    Role: Financial Coach.
                    Task: Generate a Daily Brief.

                    Rules:
                    1. STATUS: 'Excellent' | 'Good' | 'Warning' | 'At Risk'. 
                       - If spentToday > dailyCap * 1.5 -> At Risk.
                       - If spentToday > dailyCap -> Warning.
                       - Else Good/Excellent.
                    2. REASON: 1 short phrase (e.g., "High food spend", "Staying under cap").
                    3. PROJECTION: 'Safe' | 'Tight' | 'Overspend'.
                    4. DELTA: String like "+10% vs limit" or "On Track".
                    5. INSIGHT: 
                       - If Good/Excellent: 1 sentence. Positive reinforcement.
                       - If Warning/At Risk: 1 sentence. Explain consequence (e.g., "Slowing down goal by 2 days").
                    6. ACTION:
                       - If Good/Excellent: null.
                       - If Warning/At Risk: 1 specific action (e.g., "Spend $0 rest of day").
                `,
                config: {
                    responseMimeType: "application/json",
                    responseSchema: {
                        type: Type.OBJECT,
                        properties: {
                            status: { type: Type.STRING, enum: ['Excellent', 'Good', 'Warning', 'At Risk'] },
                            statusReason: { type: Type.STRING },
                            projection: {
                                type: Type.OBJECT,
                                properties: {
                                    outcome: { type: Type.STRING, enum: ['Safe', 'Tight', 'Overspend'] },
                                    delta: { type: Type.STRING }
                                }
                            },
                            insight: {
                                type: Type.OBJECT,
                                properties: {
                                    headline: { type: Type.STRING },
                                    subtext: { type: Type.STRING }
                                }
                            },
                            action: {
                                type: Type.OBJECT,
                                properties: {
                                    text: { type: Type.STRING },
                                    isActionable: { type: Type.BOOLEAN }
                                }
                            }
                        }
                    }
                }
            });

            if (response.text) {
                const aiData = JSON.parse(cleanJsonResponse(response.text));
                // Merge deterministic math with AI narrative
                return {
                    date: today.toISOString(),
                    status: aiData.status,
                    statusReason: aiData.statusReason,
                    snapshot: {
                        spentToday,
                        safeRemaining,
                        dailyCap
                    },
                    projection: aiData.projection,
                    insight: aiData.insight,
                    action: aiData.action
                };
            }
            throw new Error("No response");
        } catch (e) {
            console.error("Daily Generation Failed", e);
            // Fallback
            return {
                date: today.toISOString(),
                status: safeRemaining < 0 ? 'Warning' : 'Good',
                statusReason: safeRemaining < 0 ? 'Daily cap exceeded' : 'On track',
                snapshot: { spentToday, safeRemaining, dailyCap },
                projection: { outcome: isProjectedOver ? 'Overspend' : 'Safe', delta: isProjectedOver ? 'Over limit' : 'On track' },
                insight: { headline: "System operational. No AI narrative available." },
                action: null
            };
        }
    });
};

