        {/* Main Content */}
        <div className={`flex-1 flex flex-col relative z-10 overflow-hidden ${onboardingComplete ? 'md:pl-24' : ''} transition-all duration-300`}>
            {/* Mobile Header - Only render if onboarding is complete */}
            {onboardingComplete && (
                <div className="md:hidden h-16 bg-[#0f172a]/90 backdrop-blur-xl border-b border-white/5 flex items-center justify-between px-4 z-20">
                    <div className="flex items-center gap-2">
                        <Sparkles className="w-6 h-6 text-indigo-500" />
                        <span className="font-bold text-white">Nova</span>
                    </div>
                    <div className="flex items-center gap-3">
                        <button onClick={() => setAutoScanTrigger(true)} className="p-2 bg-slate-800 rounded-full text-indigo-400"><Zap className="w-4 h-4" /></button>
                    </div>
                </div>
            )}

            <main className="flex-1 overflow-y-auto overflow-x-hidden p-4 md:p-8 custom-scrollbar">
                <div className="w-full max-w-[1920px] mx-auto h-full">
                    {activeTab === 'dashboard' && (
                        <Dashboard 
                            accounts={accounts} 
                            transactions={transactions} 
                            goals={goals} 
                            budgets={budgets} 
                            onNavigate={handleNavigate}
                            onAddTransaction={() => handleNavigate('transactions')}
                            onAddGoal={() => handleNavigate('goals')}
                            formatCurrency={formatCurrency}
                            userPlan={userPlan}
                            onAskCoach={(q) => { setPendingChatQuery(q); handleNavigate('insights'); }}
                            insightUsage={insightUsage}
                            spendingStatus={spendingStatus}
                            currentPeriodSpend={currentPeriodSpend}
                            spendingLimit={spendingLimit}
                            spendingPeriod={spendingPeriod}
                            userName={userName}
                            isPrivacyMode={isPrivacyMode}
                            onTogglePrivacy={() => setIsPrivacyMode(!isPrivacyMode)}
                            creditScore={creditScore}
                        />
                    )}
                    {activeTab === 'transactions' && (
                        <Transactions 
                            transactions={transactions}
                            accounts={accounts}
                            onDelete={(id) => {
                                const tx = transactions.find(t => t.id === id);
                                if (tx) {
                                    setTransactions(prev => prev.filter(t => t.id !== id));
                                    // Revert balance
                                    const accIndex = accounts.findIndex(a => a.id === tx.accountId);
                                    if (accIndex >= 0) {
                                        const updated = [...accounts];
                                        if (tx.type === TransactionType.INCOME) updated[accIndex].balance -= tx.amount;
                                        else updated[accIndex].balance += tx.amount;
                                        setAccounts(updated);
                                    }
                                }
                            }}
                            onAdd={handleAddTransaction}
                            formatCurrency={formatCurrency}
                            onNavigateToAccounts={() => handleNavigate('accounts')}
                            userPlan={userPlan}
                            scanUsage={scanUsage}
                            onIncrementScan={() => handleIncrementUsage('scan')}
                            currency={currency}
                        />
                    )}
                    {activeTab === 'accounts' && (
                        <Accounts 
                            accounts={accounts}
                            budgets={budgets}
                            transactions={transactions}
                            userPlan={userPlan}
                            onAdd={(acc) => setAccounts(prev => [...prev, acc])}
                            onUpdate={(acc) => setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a))}
                            onDelete={(id) => setAccounts(prev => prev.filter(a => a.id !== id))}
                            formatCurrency={formatCurrency}
                            userName={userName}
                            userAvatar={userAvatar}
                            userAvatarZoom={userAvatarZoom}
                            userAvatarPos={userAvatarPos}
                            userBorder={userBorder}
                            onNavigate={handleNavigate}
                        />
                    )}
                    {activeTab === 'insights' && (
                        <Insights 
                            transactions={transactions}
                            goals={goals}
                            budgets={budgets}
                            userPlan={userPlan}
                            onUpgradeClick={() => handleNavigate('plans')}
                            formatCurrency={formatCurrency}
                            initialPrompt={pendingChatQuery}
                            onPromptHandled={() => setPendingChatQuery(null)}
                            onApplyBudgets={(newBudgets) => setBudgets(prev => [...prev, ...newBudgets])}
                            insightUsage={insightUsage}
                            onIncrementUsage={() => handleIncrementUsage('insight')}
                            botMode={botMode}
                            onNavigate={handleNavigate}
                            onAddGoal={(g) => setGoals(prev => [...prev, g])}
                            autoScanTriggered={autoScanTrigger}
                            activeReport={activeReport}
                            spendingLimit={spendingLimit}
                        />
                    )}
                    {activeTab === 'smart_money' && (
                        <SmartMoney 
                            initialTab={smartMoneyTab}
                            transactions={transactions}
                            accounts={accounts}
                            goals={goals}
                            formatCurrency={formatCurrency}
                            userPlan={userPlan}
                            onUpgradeClick={() => handleNavigate('plans')}
                            insightUsage={insightUsage}
                            onIncrementUsage={(n) => handleIncrementUsage('insight', n)}
                            negotiationUsage={negotiationUsage}
                            onIncrementNegotiationUsage={() => handleIncrementUsage('negotiation')}
                        />
                    )}
                    {activeTab === 'goals' && (
                        <Goals 
                            goals={goals}
                            budgets={budgets}
                            transactions={transactions}
                            onAddGoal={(g) => setGoals(prev => [...prev, g])}
                            onUpdateGoal={(g) => setGoals(prev => prev.map(goal => goal.id === g.id ? g : goal))}
                            onAddBudget={(b) => setBudgets(prev => [...prev, b])}
                            onDeleteBudget={(id) => setBudgets(prev => prev.filter(b => b.id !== id))}
                            formatCurrency={formatCurrency}
                        />
                    )}
                    {activeTab === 'plans' && (
                        <Plans 
                            currentPlan={userPlan}
                            onUpgrade={(plan) => setUserPlan(plan)}
                            onDowngrade={() => setUserPlan('free')}
                            onNavigateDashboard={() => handleNavigate('dashboard')}
                        />
                    )}
                    {activeTab === 'settings' && (
                        <Settings 
                            userName={userName}
                            userEmail={userEmail}
                            userAvatar={userAvatar}
                            userAvatarZoom={userAvatarZoom}
                            userAvatarPos={userAvatarPos}
                            userBorder={userBorder}
                            userBackground={userBackground}
                            onUpdateBackground={(bg) => setUserBackground(bg)}
                            userPlan={userPlan}
                            onUpdateProfile={handleUpdateProfile}
                            addToast={addToast}
                            onExportData={() => {
                                const data = { accounts, transactions, budgets, goals, userPlan };
                                const blob = new Blob([JSON.stringify(data)], { type: 'application/json' });
                                const url = URL.createObjectURL(blob);
                                const a = document.createElement('a');
                                a.href = url;
                                a.download = `nova_backup_${new Date().toISOString()}.json`;
                                a.click();
                            }}
                            onImportData={(file) => {
                                const reader = new FileReader();
                                reader.onload = (e) => {
                                    try {
                                        const data = JSON.parse(e.target?.result as string);
                                        if (data.accounts) setAccounts(data.accounts);
                                        if (data.transactions) setTransactions(data.transactions);
                                        if (data.budgets) setBudgets(data.budgets);
                                        if (data.goals) setGoals(data.goals);
                                        addToast('Data restored successfully', 'success');
                                    } catch (err) {
                                        addToast('Invalid backup file', 'error');
                                    }
                                };
                                reader.readAsText(file);
                            }}
                            onClearData={() => {
                                setAccounts(ACCOUNTS);
                                setTransactions(INITIAL_TRANSACTIONS);
                                setBudgets(INITIAL_BUDGETS);
                                setGoals(INITIAL_GOALS);
                                addToast('System reset complete', 'info');
                            }}
                            language={language}
                            onUpdateLanguage={setLanguage}
                            currency={currency}
                            onUpdateCurrency={setCurrency}
                            botMode={botMode}
                            onUpdateBotMode={setBotMode}
                            onDowngrade={() => setUserPlan('free')}
                            spendingLimit={spendingLimit}
                            onUpdateSpendingLimit={setSpendingLimit}
                            spendingPeriod={spendingPeriod}
                            onUpdateSpendingPeriod={setSpendingPeriod}
                            creditScore={creditScore}
                            onUpdateCreditScore={setCreditScore}
                        />
                    )}
                    {activeTab === 'investment' && (
                        <Investment 
                            accounts={accounts}
                            formatCurrency={formatCurrency}
                            userPlan={userPlan}
                        />
                    )}
                    {activeTab === 'upcoming' && <UpcomingFeatures />}
                </div>
            </main>

            {isLoggedIn && !onboardingComplete && (
                <OnboardingModal onComplete={(name, lang, period, limit) => {
                    setUserName(name);
                    setLanguage(lang);
                    setSpendingPeriod(period);
                    setSpendingLimit(limit);
                    setOnboardingComplete(true);
                    localStorage.setItem('nova_onboarding_complete', 'true');
                    addToast("Core initialized. Welcome to Nova.", "success");
                }} />
            )}

            {/* FIRST TRANSACTION ONBOARDING - Triggers after profile setup if no data exists */}
            {isLoggedIn && onboardingComplete && transactions.length === 0 && (
                <FirstTransactionOnboarding onAdd={handleAddTransaction} userName={userName} />
            )}

            {/* Mobile Nav - Only render if onboarding is complete */}
            {onboardingComplete && (
                <MobileNav 
                    activeTab={activeTab} 
                    onNavigate={handleNavigate} 
                    onAddTransaction={() => handleNavigate('transactions')} 
                />
            )}

            <ToastContainer toasts={toasts} onRemove={removeToast} />

            {/* Floating Assistant - Only render if onboarding is complete */}
            {onboardingComplete && (
                <FloatingAssistant 
                    transactions={transactions} 
                    budgets={budgets} 
                    userPlan={userPlan} 
                    botMode={botMode}
                    onOpenChat={(q) => { setPendingChatQuery(q); handleNavigate('insights'); }}
                    isVisible={activeTab !== 'insights'}
                    insightUsage={insightUsage}
                />
            )}

            {isLogoutModalOpen && (
                <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-fade-in">
                    <div className="bg-slate-900 border border-white/10 rounded-2xl p-6 w-full max-w-sm shadow-2xl animate-slide-up">
                        <h3 className="text-lg font-bold text-white mb-2">Terminate Session?</h3>
                        <p className="text-slate-400 text-sm mb-6">Your local data will persist, but you will need to re-authenticate to access the vault.</p>
                        <div className="flex justify-end gap-3">
                            <button onClick={() => setIsLogoutModalOpen(false)} className="px-4 py-2 text-slate-300 hover:text-white font-medium">Cancel</button>
                            <button 
                                onClick={() => {
                                    setIsLoggedIn(false);
                                    setIsLogoutModalOpen(false);
                                    localStorage.removeItem('nova_auth_token');
                                }} 
                                className="px-4 py-2 bg-rose-600 hover:bg-rose-500 text-white rounded-lg font-bold shadow-lg"
                            >
                                Logout
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Account } from '../types';
import { Landmark, ArrowRight, Wallet, CreditCard, DollarSign } from 'lucide-react';

interface FirstAccountOnboardingProps {
  onAdd: (account: Account) => void;
  userName: string;
}

const FirstAccountOnboarding: React.FC<FirstAccountOnboardingProps> = ({ onAdd, userName }) => {
  const [name, setName] = useState('');
  const [balance, setBalance] = useState('');
  const [type, setType] = useState<Account['type']>('Checking');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name) return;

    const newAccount: Account = {
      id: Date.now().toString(),
      name,
      type,
      balance: parseFloat(balance) || 0,
      institution: 'Manual Entry',
      color: '#6366f1' // Default Indigo
    };
    onAdd(newAccount);
  };

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-[#020617] animate-fade-in">
        <div className="w-full max-w-lg bg-[#0f172a] border border-white/10 rounded-[2.5rem] shadow-2xl overflow-hidden relative animate-slide-up">
            <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-emerald-500 to-teal-500"></div>

            <div className="p-10">
                <div className="w-16 h-16 bg-emerald-500/10 rounded-2xl flex items-center justify-center mb-6 border border-emerald-500/20">
                    <Landmark className="w-8 h-8 text-emerald-400" />
                </div>

                <h2 className="text-3xl font-black text-white mb-2 tracking-tight">Establish Capital Node</h2>
                <p className="text-slate-400 text-sm font-medium leading-relaxed mb-8">
                    {userName}, to begin tracking your financial topology, we need to establish your primary account.
                </p>

                <form onSubmit={handleSubmit} className="space-y-6">
                    {/* Account Name */}
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Account Name</label>
                        <input 
                            type="text"
                            value={name}
                            onChange={(e) => setName(e.target.value)}
                            className="w-full bg-slate-950 border border-white/10 rounded-xl py-3 px-4 text-white text-sm focus:outline-none focus:border-emerald-500 transition-all placeholder:text-slate-700 font-bold"
                            placeholder="e.g. Primary Checking"
                            autoFocus
                            required
                        />
                    </div>

                    {/* Type Selection */}
                    <div className="grid grid-cols-2 gap-3">
                        {['Checking', 'Savings', 'Credit Card', 'Investment'].map((t) => (
                            <button
                                key={t}
                                type="button"
                                onClick={() => setType(t as any)}
                                className={`flex items-center gap-2 p-3 rounded-xl border text-xs font-bold transition-all ${type === t ? 'bg-emerald-600/20 border-emerald-500 text-emerald-400' : 'bg-slate-900 border-white/5 text-slate-500 hover:border-white/20 hover:text-slate-300'}`}
                            >
                                {t === 'Checking' && <Wallet className="w-4 h-4" />}
                                {t === 'Savings' && <Landmark className="w-4 h-4" />}
                                {t === 'Credit Card' && <CreditCard className="w-4 h-4" />}
                                {t === 'Investment' && <DollarSign className="w-4 h-4" />}
                                {t}
                            </button>
                        ))}
                    </div>

                    {/* Starting Balance */}
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Current Balance</label>
                        <div className="relative group">
                            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 font-bold">$</span>
                            <input 
                                type="number" 
                                step="0.01"
                                value={balance}
                                onChange={(e) => setBalance(e.target.value)}
                                className="w-full bg-slate-950 border border-white/10 rounded-xl py-3 pl-8 pr-4 text-white text-lg font-mono focus:outline-none focus:border-emerald-500 transition-all placeholder:text-slate-800"
                                placeholder="0.00"
                                required
                            />
                        </div>
                    </div>

                    <button 
                        type="submit"
                        disabled={!name}
                        className="w-full py-4 bg-emerald-600 hover:bg-emerald-500 text-white font-black uppercase text-xs tracking-[0.2em] rounded-xl shadow-lg shadow-emerald-500/20 active:scale-95 transition-all flex items-center justify-center gap-2 mt-6 disabled:opacity-50 disabled:grayscale"
                    >
                        Create Account <ArrowRight className="w-4 h-4" />
                    </button>
                </form>
            </div>
        </div>
    </div>
  );
};

export default FirstAccountOnboarding;

import React, { useState } from 'react';
import { Transaction, TransactionType, Category, Account } from '../types';
import { DollarSign, ArrowRight, Rocket } from 'lucide-react';

interface FirstTransactionOnboardingProps {
  onAdd: (t: Transaction) => void;
  userName: string;
  accounts: Account[];
}

const FirstTransactionOnboarding: React.FC<FirstTransactionOnboardingProps> = ({ onAdd, userName, accounts }) => {
  const [amount, setAmount] = useState('');
  const [merchant, setMerchant] = useState('');
  const [category, setCategory] = useState<Category>(Category.FOOD);
  const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);

  // Default to the first account created
  const defaultAccountId = accounts.length > 0 ? accounts[0].id : 'manual';
  const [accountId, setAccountId] = useState(defaultAccountId);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!amount || !merchant) return;

    const newTx: Transaction = {
      id: Date.now().toString(),
      date: new Date().toISOString().split('T')[0],
      merchant,
      amount: parseFloat(amount),
      category,
      type,
      accountId, 
      notes: 'First calibration entry'
    };
    onAdd(newTx);
  };

  const accountName = accounts.find(a => a.id === accountId)?.name || 'Manual';

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-[#020617] animate-fade-in">
        <div className="w-full max-w-lg bg-[#0f172a] border border-white/10 rounded-[2.5rem] shadow-2xl overflow-hidden relative animate-slide-up">
            <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-indigo-500 to-purple-500"></div>

            <div className="p-10">
                <div className="w-16 h-16 bg-indigo-500/10 rounded-2xl flex items-center justify-center mb-6 border border-indigo-500/20">
                    <Rocket className="w-8 h-8 text-indigo-400" />
                </div>

                <h2 className="text-3xl font-black text-white mb-2 tracking-tight">System Calibration</h2>
                <p className="text-slate-400 text-sm font-medium leading-relaxed mb-8">
                    Account <span className="text-indigo-400 font-bold">{accountName}</span> established. Now, log your first interaction to initialize the graph.
                </p>

                <form onSubmit={handleSubmit} className="space-y-6">
                    {/* Type Toggle */}
                    <div className="flex bg-slate-900 p-1 rounded-xl border border-white/5">
                        <button
                            type="button"
                            onClick={() => setType(TransactionType.EXPENSE)}
                            className={`flex-1 py-3 rounded-lg text-xs font-black uppercase tracking-widest transition-all ${type === TransactionType.EXPENSE ? 'bg-rose-500 text-white shadow-lg' : 'text-slate-500 hover:text-white'}`}
                        >
                            Expense
                        </button>
                        <button
                            type="button"
                            onClick={() => setType(TransactionType.INCOME)}
                            className={`flex-1 py-3 rounded-lg text-xs font-black uppercase tracking-widest transition-all ${type === TransactionType.INCOME ? 'bg-emerald-500 text-white shadow-lg' : 'text-slate-500 hover:text-white'}`}
                        >
                            Income
                        </button>
                    </div>

                    {/* Amount */}
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Amount</label>
                        <div className="relative group">
                            <DollarSign className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-500 group-focus-within:text-white transition-colors" />
                            <input 
                                type="number" 
                                value={amount}
                                onChange={(e) => setAmount(e.target.value)}
                                className="w-full bg-slate-950 border border-white/10 rounded-xl py-4 pl-12 pr-4 text-2xl font-bold text-white focus:outline-none focus:border-indigo-500 transition-all placeholder:text-slate-800"
                                placeholder="0.00"
                                autoFocus
                                required
                            />
                        </div>
                    </div>

                    {/* Details Grid */}
                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Description</label>
                            <input 
                                type="text"
                                value={merchant}
                                onChange={(e) => setMerchant(e.target.value)}
                                className="w-full bg-slate-950 border border-white/10 rounded-xl py-3 px-4 text-white text-sm focus:outline-none focus:border-indigo-500 transition-all placeholder:text-slate-700"
                                placeholder={type === TransactionType.EXPENSE ? "e.g. Coffee" : "e.g. Salary"}
                                required
                            />
                        </div>
                        <div className="space-y-2">
                            <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Category</label>
                            <select 
                                value={category}
                                onChange={(e) => setCategory(e.target.value as Category)}
                                className="w-full bg-slate-950 border border-white/10 rounded-xl py-3 px-4 text-white text-sm focus:outline-none focus:border-indigo-500 transition-all appearance-none cursor-pointer"
                            >
                                {Object.values(Category).map(c => (
                                    <option key={c} value={c}>{c}</option>
                                ))}
                            </select>
                        </div>
                    </div>

                    <button 
                        type="submit"
                        className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white font-black uppercase text-xs tracking-[0.2em] rounded-xl shadow-lg shadow-indigo-500/20 active:scale-95 transition-all flex items-center justify-center gap-2 mt-4"
                    >
                        Initialize Dashboard <ArrowRight className="w-4 h-4" />
                    </button>
                </form>
            </div>
        </div>
    </div>
  );
};

export default FirstTransactionOnboarding;

import React, { useState, useEffect, useMemo } from 'react';
import { Account, Budget, Goal, Transaction, UserPlan, ToastMessage, BotMode, Currency, Language, TransactionType, SpendingPeriod, SpendingStatus, ReportType } from '../types';
import { ACCOUNTS, INITIAL_TRANSACTIONS, INITIAL_BUDGETS, INITIAL_GOALS, NAV_ITEMS, TRANSLATIONS } from '../constants';
import { evaluateSpending } from '../services/ruleEngine';
import Dashboard from './Dashboard';
import Transactions from './Transactions';
import Accounts from './Accounts';
import Insights from './Insights';
import Goals from './Goals';
import Plans from './Plans';
import Settings from './Settings';
import SmartMoney from './SmartMoney';
import Investment from './Investment';
import UpcomingFeatures from './UpcomingFeatures';
import LandingPage from './LandingPage';
import OnboardingModal from './OnboardingModal';
import FirstTransactionOnboarding from './FirstTransactionOnboarding';
import FirstAccountOnboarding from './FirstAccountOnboarding';
import ToastContainer from './Toast';
import FloatingAssistant from './FloatingAssistant';
import MobileNav from './MobileNav';
import { Sparkles, LogOut, Zap, Shield, EyeOff, LayoutDashboard, CreditCard, Landmark, Target, Settings as SettingsIcon, Lock, Eye } from 'lucide-react';

const getMonthlyUsage = (key: string) => {
    try {
        const item = localStorage.getItem(key);
        if (!item) return 0;
        const parsed = JSON.parse(item);
        const now = new Date();
        if (parsed.month !== now.getMonth() || parsed.year !== now.getFullYear()) return 0;
        return parsed.count || 0;
    } catch (e) { return 0; }
};

const safeSetItem = (key: string, value: string) => {
    try { localStorage.setItem(key, value); } catch (e) { console.warn(`Storage quota exceeded for ${key}`); }
};

const PINNABLE_FEATURES = ['budget-monitor', 'sandbox-link', 'goal-tracker', 'system-alerts', 'neural-quota'];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [smartMoneyTab, setSmartMoneyTab] = useState('burn_vector');
  const [activeReport, setActiveReport] = useState<ReportType>(null);
  const [isPrivacyMode, setIsPrivacyMode] = useState(() => localStorage.getItem('nova_privacy_mode') === 'true');
  const [isPinMode, setIsPinMode] = useState(false);
  const [autoScanTrigger, setAutoScanTrigger] = useState(false);

  const [onboardingComplete, setOnboardingComplete] = useState(() => localStorage.getItem('nova_onboarding_complete') === 'true');

  const [spendingLimit, setSpendingLimit] = useState<number>(() => {
      const stored = localStorage.getItem('nova_spending_limit');
      if (!stored) return 1000;
      const parsed = parseFloat(stored);
      return Number.isFinite(parsed) && parsed > 0 ? parsed : 1000;
  });

  const [spendingPeriod, setSpendingPeriod] = useState<SpendingPeriod>(() => (localStorage.getItem('nova_spending_period') as SpendingPeriod) || 'monthly');

  const [pinnedIds, setPinnedIds] = useState<string[]>(() => {
    try {
        const saved = localStorage.getItem('nova_pinned_ids');
        return saved ? JSON.parse(saved) : []; 
    } catch { return []; }
  });

  const [featureUsage, setFeatureUsage] = useState<Record<string, number>>(() => {
      try {
          const saved = localStorage.getItem('nova_feature_usage');
          return saved ? JSON.parse(saved) : {};
      } catch { return {}; }
  });

  const [accounts, setAccounts] = useState<Account[]>(() => {
      const saved = localStorage.getItem('nova_accounts');
      return saved ? JSON.parse(saved) : ACCOUNTS;
  });
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
      const saved = localStorage.getItem('nova_transactions');
      return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });
  const [budgets, setBudgets] = useState<Budget[]>(() => {
      const saved = localStorage.getItem('nova_budgets');
      return saved ? JSON.parse(saved) : INITIAL_BUDGETS;
  });
  const [goals, setGoals] = useState<Goal[]>(() => {
      const saved = localStorage.getItem('nova_goals');
      return saved ? JSON.parse(saved) : INITIAL_GOALS;
  });

  const [userPlan, setUserPlan] = useState<UserPlan>(() => localStorage.getItem('nova_user_plan') as UserPlan || 'free');
  const [insightUsage, setInsightUsage] = useState(() => getMonthlyUsage('nova_insight_usage'));
  const [scanUsage, setScanUsage] = useState(() => getMonthlyUsage('nova_scan_usage'));
  const [negotiationUsage, setNegotiationUsage] = useState(() => getMonthlyUsage('nova_negotiation_usage'));

  const [isLoggedIn, setIsLoggedIn] = useState(() => localStorage.getItem('nova_auth_token') !== null);
  const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [botMode, setBotMode] = useState<BotMode>(() => (localStorage.getItem('nova_bot_mode') as BotMode) || 'ruthless');
  const [pendingChatQuery, setPendingChatQuery] = useState<string | null>(null);

  const [userName, setUserName] = useState(() => localStorage.getItem('nova_user_name') || 'Pilot');
  const [userEmail, setUserEmail] = useState(() => localStorage.getItem('nova_user_email') || 'pilot@nova.io');
  const [userAvatar, setUserAvatar] = useState(() => localStorage.getItem('nova_user_avatar') || '');
  const [userAvatarZoom, setUserAvatarZoom] = useState(() => parseFloat(localStorage.getItem('nova_user_avatar_zoom') || '1'));
  const [userAvatarPos, setUserAvatarPos] = useState(() => {
      try {
          const saved = localStorage.getItem('nova_user_avatar_pos');
          return saved ? JSON.parse(saved) : { x: 0, y: 0 };
      } catch { return { x: 0, y: 0 }; }
  });
  const [userBorder, setUserBorder] = useState(() => localStorage.getItem('nova_user_border') || 'default');
  const [userBackground, setUserBackground] = useState(() => localStorage.getItem('nova_user_bg') || '');

  // Credit Score State - Default to 0 (Unset) to force user calibration
  const [creditScore, setCreditScore] = useState<number>(() => {
      const stored = localStorage.getItem('nova_credit_score');
      return stored ? parseInt(stored, 10) : 0;
  });

  const [currency, setCurrency] = useState<Currency>(() => (localStorage.getItem('nova_currency') as Currency) || 'USD');
  const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('nova_language') as Language) || 'en');

  // Persistence
  useEffect(() => safeSetItem('nova_accounts', JSON.stringify(accounts)), [accounts]);
  useEffect(() => safeSetItem('nova_transactions', JSON.stringify(transactions)), [transactions]);
  useEffect(() => safeSetItem('nova_budgets', JSON.stringify(budgets)), [budgets]);
  useEffect(() => safeSetItem('nova_goals', JSON.stringify(goals)), [goals]);
  useEffect(() => safeSetItem('nova_user_plan', userPlan), [userPlan]);
  useEffect(() => safeSetItem('nova_currency', currency), [currency]);
  useEffect(() => safeSetItem('nova_language', language), [language]);
  useEffect(() => safeSetItem('nova_bot_mode', botMode), [botMode]);
  useEffect(() => safeSetItem('nova_privacy_mode', isPrivacyMode.toString()), [isPrivacyMode]);
  useEffect(() => safeSetItem('nova_pinned_ids', JSON.stringify(pinnedIds)), [pinnedIds]);
  useEffect(() => safeSetItem('nova_feature_usage', JSON.stringify(featureUsage)), [featureUsage]);
  useEffect(() => safeSetItem('nova_spending_limit', spendingLimit.toString()), [spendingLimit]);
  useEffect(() => safeSetItem('nova_spending_period', spendingPeriod), [spendingPeriod]);
  useEffect(() => safeSetItem('nova_user_bg', userBackground), [userBackground]);
  useEffect(() => safeSetItem('nova_credit_score', creditScore.toString()), [creditScore]);

  // Derived State
  const currentPeriodSpend = useMemo(() => {
      const now = new Date();
      return transactions
        .filter(t => {
            const d = new Date(t.date);
            if (t.type !== TransactionType.EXPENSE) return false;

            if (spendingPeriod === 'monthly') {
                return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear();
            } else {
                // Weekly logic: simple 7 day lookback for now
                const oneWeekAgo = new Date();
                oneWeekAgo.setDate(now.getDate() - 7);
                return d >= oneWeekAgo && d <= now;
            }
        })
        .reduce((acc, t) => acc + t.amount, 0);
  }, [transactions, spendingPeriod]);

  const spendingStatus = useMemo(() => evaluateSpending(currentPeriodSpend, spendingLimit), [currentPeriodSpend, spendingLimit]);

  // Enhanced Format Currency with Privacy Logic
  const formatCurrency = (amount: number) => {
    if (isPrivacyMode) return '••••••';
    return new Intl.NumberFormat(language === 'vi' ? 'vi-VN' : 'en-US', {
      style: 'currency',
      currency: currency
    }).format(amount);
  };

  const addToast = (message: string, type: ToastMessage['type'] = 'info') => {
    setToasts(prev => [...prev, { id: Date.now().toString(), type, message }]);
  };

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const handleNavigate = (tab: string, params?: any) => {
    setActiveTab(tab);
    if (tab === 'smart_money' && params?.tab) {
        setSmartMoneyTab(params.tab);
    }
    if (tab === 'insights' && params?.reportType) {
        setActiveReport(params.reportType);
    }
  };

  const handleAddAccount = (newAccount: Account) => {
      setAccounts(prev => [...prev, newAccount]);
      addToast('Account established successfully', 'success');
  };

  const handleAddTransaction = (newTx: Transaction) => {
      setTransactions(prev => [newTx, ...prev]);

      const accIndex = accounts.findIndex(a => a.id === newTx.accountId);
      if (accIndex >= 0) {
          const updatedAccounts = [...accounts];
          if (newTx.type === TransactionType.INCOME) {
              updatedAccounts[accIndex].balance += newTx.amount;
          } else {
              updatedAccounts[accIndex].balance -= newTx.amount;
          }
          setAccounts(updatedAccounts);
      }
      addToast('Transaction recorded successfully', 'success');
  };

  const handleUpdateProfile = (name: string, email: string, avatar: string, zoom: number, pos: {x:number, y:number}, border: string) => {
      setUserName(name);
      setUserEmail(email);
      setUserAvatar(avatar);
      setUserAvatarZoom(zoom);
      setUserAvatarPos(pos);
      setUserBorder(border);
      localStorage.setItem('nova_user_name', name);
      localStorage.setItem('nova_user_email', email);
      localStorage.setItem('nova_user_avatar', avatar);
      localStorage.setItem('nova_user_avatar_zoom', zoom.toString());
      localStorage.setItem('nova_user_avatar_pos', JSON.stringify(pos));
      localStorage.setItem('nova_user_border', border);
  };

  const handleIncrementUsage = (type: 'insight' | 'scan' | 'negotiation', amount = 1) => {
      const key = `nova_${type}_usage`;
      const now = new Date();
      const current = type === 'insight' ? insightUsage : type === 'scan' ? scanUsage : negotiationUsage;
      const newVal = current + amount;

      const record = { count: newVal, month: now.getMonth(), year: now.getFullYear() };
      localStorage.setItem(key, JSON.stringify(record));

      if (type === 'insight') setInsightUsage(newVal);
      else if (type === 'scan') setScanUsage(newVal);
      else setNegotiationUsage(newVal);
  };

  if (!isLoggedIn) {
      return (
          <>
            <LandingPage onLoginSuccess={(name) => {
                setUserName(name);
                setIsLoggedIn(true);
                localStorage.setItem('nova_auth_token', 'mock_token');
                localStorage.setItem('nova_user_name', name);
                addToast(`Welcome back, ${name}. Vault unlocked.`, 'success');
            }} />
            <ToastContainer toasts={toasts} onRemove={removeToast} />
          </>
      );
  }

  return (
    <div className="flex h-screen bg-[#020617] text-slate-200 font-sans selection:bg-indigo-500/30 overflow-hidden" 
         style={{ backgroundImage: userBackground ? `url(${userBackground})` : 'none', backgroundSize: 'cover', backgroundPosition: 'center' }}>

        {/* Dark Overlay for Readability if Background is set */}
        {userBackground && <div className="absolute inset-0 bg-[#020617]/80 backdrop-blur-[2px] z-0"></div>}

        {/* MODERN GLASS SIDEBAR - Only render if onboarding is complete */}
        {onboardingComplete && (
            <div className="hidden md:flex flex-col h-screen fixed left-0 top-0 z-50 w-24 hover:w-80 transition-all duration-500 ease-[cubic-bezier(0.25,1,0.5,1)] bg-[#0f172a]/60 backdrop-blur-2xl border-r border-white/5 shadow-[10px_0_40px_rgba(0,0,0,0.5)] group overflow-hidden">

                {/* Logo Section */}
                <div className="h-28 flex items-center px-6 shrink-0 relative">
                    <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-indigo-600 to-violet-600 flex items-center justify-center shadow-lg shadow-indigo-500/30 shrink-0 z-20 ring-1 ring-white/20 group-hover:scale-110 transition-transform duration-500">
                        <Sparkles className="w-6 h-6 text-white" />
                    </div>
                    <div className="ml-5 opacity-0 group-hover:opacity-100 transition-all duration-500 transform translate-x-[-20px] group-hover:translate-x-0 whitespace-nowrap">
                        <h1 className="text-3xl font-black text-white tracking-tighter drop-shadow-md">NOVA<span className="text-indigo-400">.OS</span></h1>
                        <p className="text-[9px] font-bold text-slate-400 uppercase tracking-[0.3em] ml-0.5">Finance Core</p>
                    </div>

                    {/* Ambient Glow */}
                    <div className="absolute top-1/2 left-6 -translate-y-1/2 w-20 h-20 bg-indigo-500/20 rounded-full blur-3xl group-hover:bg-indigo-500/30 transition-all duration-700"></div>
                </div>

                {/* Navigation Items */}
                <nav className="flex-1 overflow-y-auto overflow-x-hidden px-4 space-y-2 custom-scrollbar py-4">
                    {NAV_ITEMS.map((item) => (
                        <button
                            key={item.id}
                            onClick={() => handleNavigate(item.id)}
                            className={`relative w-full flex items-center h-14 rounded-[1.2rem] transition-all duration-300 group/item overflow-hidden ${
                                activeTab === item.id 
                                ? 'bg-gradient-to-r from-indigo-600 to-violet-600 text-white shadow-lg shadow-indigo-500/20' 
                                : 'text-slate-400 hover:bg-white/5 hover:text-white'
                            }`}
                        >
                            {/* Hover Gradient Overlay */}
                            <div className="absolute inset-0 bg-gradient-to-r from-white/10 to-transparent opacity-0 group-hover/item:opacity-100 transition-opacity duration-300"></div>

                            {/* Icon Container */}
                            <div className="w-16 h-full flex items-center justify-center shrink-0 relative z-10">
                                <item.icon className={`w-6 h-6 transition-all duration-500 ${
                                    activeTab === item.id 
                                    ? 'text-white scale-110 drop-shadow-md' 
                                    : 'group-hover/item:text-indigo-300 group-hover/item:scale-110'
                                }`} />
                            </div>

                            {/* Text Label */}
                            <div className="opacity-0 group-hover:opacity-100 transform translate-x-4 group-hover:translate-x-0 transition-all duration-500 whitespace-nowrap font-bold text-sm tracking-wide relative z-10 flex items-center gap-2">
                                {item.label}
                                {activeTab === item.id && <div className="w-1.5 h-1.5 rounded-full bg-white animate-pulse shadow-[0_0_5px_white]"></div>}
                            </div>
                        </button>
                    ))}
                </nav>

                {/* Privacy Mode Toggle - Above User Profile */}
                <div className="px-4 pb-2 pt-2 mt-auto">
                    <button 
                        onClick={() => setIsPrivacyMode(!isPrivacyMode)}
                        className={`w-full flex items-center h-12 rounded-xl transition-all ${isPrivacyMode ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' : 'bg-white/5 text-slate-400 hover:bg-white/10 hover:text-white'}`}
                    >
                        <div className="w-16 flex items-center justify-center shrink-0">
                             {isPrivacyMode ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                        </div>
                        <span className="whitespace-nowrap text-xs font-bold uppercase tracking-widest opacity-0 group-hover:opacity-100 transition-all duration-500 transform translate-x-4 group-hover:translate-x-0">
                            Privacy {isPrivacyMode ? 'On' : 'Off'}
                        </span>
                    </button>
                </div>

                {/* User Footer */}
                <div className="p-4 bg-gradient-to-t from-black/40 to-transparent backdrop-blur-md border-t border-white/5">
                    <div 
                        onClick={() => handleNavigate('settings')}
                        className="relative overflow-hidden rounded-2xl bg-white/5 border border-white/10 p-2 cursor-pointer transition-all duration-300 hover:bg-white/10 hover:border-white/20 group/profile"
                    >
                        <div className="flex items-center gap-3">
                            <div className="w-12 h-12 rounded-xl bg-slate-800 shrink-0 overflow-hidden relative border border-white/10 shadow-inner">
                                {userAvatar ? <img src={userAvatar} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-white font-black bg-gradient-to-br from-slate-700 to-slate-900">{userName.charAt(0)}</div>}
                            </div>

                            <div className="opacity-0 group-hover:opacity-100 transition-all duration-500 transform translate-x-4 group-hover:translate-x-0 whitespace-nowrap min-w-0 flex flex-col justify-center">
                                <div className="font-bold text-white text-sm truncate">{userName}</div>
                                <div className="flex items-center gap-1.5 mt-0.5">
                                    <span className={`w-1.5 h-1.5 rounded-full ${userPlan === 'ultra' ? 'bg-purple-500' : 'bg-amber-500'} animate-pulse`}></span>
                                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{userPlan} Pilot</span>
                                </div>
                            </div>
                        </div>

                        <div className="absolute right-2 top-1/2 -translate-y-1/2 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-all duration-300 translate-x-4 group-hover:translate-x-0 delay-100">
                            <button 
                                onClick={(e) => { e.stopPropagation(); setIsLogoutModalOpen(true); }}
                                className="p-2 rounded-lg text-slate-400 hover:text-rose-400 hover:bg-rose-500/10 transition-colors"
                                title="Logout"
                            >
                                <LogOut className="w-4 h-4" />
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        )}

        {/* Main Content */}
        <div className={`flex-1 flex flex-col relative z-10 overflow-hidden ${onboardingComplete ? 'md:pl-24' : ''} transition-all duration-300`}>
            {/* Mobile Header - Only render if onboarding is complete */}
            {onboardingComplete && (
                <div className="md:hidden h-16 bg-[#0f172a]/90 backdrop-blur-xl border-b border-white/5 flex items-center justify-between px-4 z-20">
                    <div className="flex items-center gap-2">
                        <Sparkles className="w-6 h-6 text-indigo-500" />
                        <span className="font-bold text-white">Nova</span>
                    </div>
                    <div className="flex items-center gap-3">
                        <button onClick={() => setAutoScanTrigger(true)} className="p-2 bg-slate-800 rounded-full text-indigo-400"><Zap className="w-4 h-4" /></button>
                    </div>
                </div>
            )}

            <main className="flex-1 overflow-y-auto overflow-x-hidden p-4 md:p-8 custom-scrollbar">
                <div className="w-full max-w-[1920px] mx-auto h-full">
                    {activeTab === 'dashboard' && (
                        <Dashboard 
                            accounts={accounts} 
                            transactions={transactions} 
                            goals={goals} 
                            budgets={budgets} 
                            onNavigate={handleNavigate}
                            onAddTransaction={() => handleNavigate('transactions')}
                            onAddGoal={() => handleNavigate('goals')}
                            formatCurrency={formatCurrency}
                            userPlan={userPlan}
                            onAskCoach={(q) => { setPendingChatQuery(q); handleNavigate('insights'); }}
                            insightUsage={insightUsage}
                            spendingStatus={spendingStatus}
                            currentPeriodSpend={currentPeriodSpend}
                            spendingLimit={spendingLimit}
                            spendingPeriod={spendingPeriod}
                            userName={userName}
                            isPrivacyMode={isPrivacyMode}
                            onTogglePrivacy={() => setIsPrivacyMode(!isPrivacyMode)}
                            creditScore={creditScore}
                        />
                    )}
                    {activeTab === 'transactions' && (
                        <Transactions 
                            transactions={transactions}
                            accounts={accounts}
                            onDelete={(id) => {
                                const tx = transactions.find(t => t.id === id);
                                if (tx) {
                                    setTransactions(prev => prev.filter(t => t.id !== id));
                                    // Revert balance
                                    const accIndex = accounts.findIndex(a => a.id === tx.accountId);
                                    if (accIndex >= 0) {
                                        const updated = [...accounts];
                                        if (tx.type === TransactionType.INCOME) updated[accIndex].balance -= tx.amount;
                                        else updated[accIndex].balance += tx.amount;
                                        setAccounts(updated);
                                    }
                                }
                            }}
                            onAdd={handleAddTransaction}
                            formatCurrency={formatCurrency}
                            onNavigateToAccounts={() => handleNavigate('accounts')}
                            userPlan={userPlan}
                            scanUsage={scanUsage}
                            onIncrementScan={() => handleIncrementUsage('scan')}
                            currency={currency}
                        />
                    )}
                    {activeTab === 'accounts' && (
                        <Accounts 
                            accounts={accounts}
                            budgets={budgets}
                            transactions={transactions}
                            userPlan={userPlan}
                            onAdd={(acc) => setAccounts(prev => [...prev, acc])}
                            onUpdate={(acc) => setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a))}
                            onDelete={(id) => setAccounts(prev => prev.filter(a => a.id !== id))}
                            formatCurrency={formatCurrency}
                            userName={userName}
                            userAvatar={userAvatar}
                            userAvatarZoom={userAvatarZoom}
                            userAvatarPos={userAvatarPos}
                            userBorder={userBorder}
                            onNavigate={handleNavigate}
                        />
                    )}
                    {activeTab === 'insights' && (
                        <Insights 
                            transactions={transactions}
                            goals={goals}
                            budgets={budgets}
                            userPlan={userPlan}
                            onUpgradeClick={() => handleNavigate('plans')}
                            formatCurrency={formatCurrency}
                            initialPrompt={pendingChatQuery}
                            onPromptHandled={() => setPendingChatQuery(null)}
                            onApplyBudgets={(newBudgets) => setBudgets(prev => [...prev, ...newBudgets])}
                            insightUsage={insightUsage}
                            onIncrementUsage={() => handleIncrementUsage('insight')}
                            botMode={botMode}
                            onNavigate={handleNavigate}
                            onAddGoal={(g) => setGoals(prev => [...prev, g])}
                            autoScanTriggered={autoScanTrigger}
                            activeReport={activeReport}
                            spendingLimit={spendingLimit}
                        />
                    )}
                    {activeTab === 'smart_money' && (
                        <SmartMoney 
                            initialTab={smartMoneyTab}
                            transactions={transactions}
                            accounts={accounts}
                            goals={goals}
                            formatCurrency={formatCurrency}
                            userPlan={userPlan}
                            onUpgradeClick={() => handleNavigate('plans')}
                            insightUsage={insightUsage}
                            onIncrementUsage={(n) => handleIncrementUsage('insight', n)}
                            negotiationUsage={negotiationUsage}
                            onIncrementNegotiationUsage={() => handleIncrementUsage('negotiation')}
                        />
                    )}
                    {activeTab === 'goals' && (
                        <Goals 
                            goals={goals}
                            budgets={budgets}
                            transactions={transactions}
                            onAddGoal={(g) => setGoals(prev => [...prev, g])}
                            onUpdateGoal={(g) => setGoals(prev => prev.map(goal => goal.id === g.id ? g : goal))}
                            onAddBudget={(b) => setBudgets(prev => [...prev, b])}
                            onDeleteBudget={(id) => setBudgets(prev => prev.filter(b => b.id !== id))}
                            formatCurrency={formatCurrency}
                        />
                    )}
                    {activeTab === 'plans' && (
                        <Plans 
                            currentPlan={userPlan}
                            onUpgrade={(plan) => setUserPlan(plan)}
                            onDowngrade={() => setUserPlan('free')}
                            onNavigateDashboard={() => handleNavigate('dashboard')}
                        />
                    )}
                    {activeTab === 'settings' && (
                        <Settings 
                            userName={userName}
                            userEmail={userEmail}
                            userAvatar={userAvatar}
                            userAvatarZoom={userAvatarZoom}
                            userAvatarPos={userAvatarPos}
                            userBorder={userBorder}
                            userBackground={userBackground}
                            onUpdateBackground={(bg) => setUserBackground(bg)}
                            userPlan={userPlan}
                            onUpdateProfile={handleUpdateProfile}
                            addToast={addToast}
                            onExportData={() => {
                                const data = { accounts, transactions, budgets, goals, userPlan };
                                const blob = new Blob([JSON.stringify(data)], { type: 'application/json' });
                                const url = URL.createObjectURL(blob);
                                const a = document.createElement('a');
                                a.href = url;
                                a.download = `nova_backup_${new Date().toISOString()}.json`;
                                a.click();
                            }}
                            onImportData={(file) => {
                                const reader = new FileReader();
                                reader.onload = (e) => {
                                    try {
                                        const data = JSON.parse(e.target?.result as string);
                                        if (data.accounts) setAccounts(data.accounts);
                                        if (data.transactions) setTransactions(data.transactions);
                                        if (data.budgets) setBudgets(data.budgets);
                                        if (data.goals) setGoals(data.goals);
                                        addToast('Data restored successfully', 'success');
                                    } catch (err) {
                                        addToast('Invalid backup file', 'error');
                                    }
                                };
                                reader.readAsText(file);
                            }}
                            onClearData={() => {
                                setAccounts(ACCOUNTS);
                                setTransactions(INITIAL_TRANSACTIONS);
                                setBudgets(INITIAL_BUDGETS);
                                setGoals(INITIAL_GOALS);
                                addToast('System reset complete', 'info');
                            }}
                            language={language}
                            onUpdateLanguage={setLanguage}
                            currency={currency}
                            onUpdateCurrency={setCurrency}
                            botMode={botMode}
                            onUpdateBotMode={setBotMode}
                            onDowngrade={() => setUserPlan('free')}
                            spendingLimit={spendingLimit}
                            onUpdateSpendingLimit={setSpendingLimit}
                            spendingPeriod={spendingPeriod}
                            onUpdateSpendingPeriod={setSpendingPeriod}
                            creditScore={creditScore}
                            onUpdateCreditScore={setCreditScore}
                        />
                    )}
                    {activeTab === 'investment' && (
                        <Investment 
                            accounts={accounts}
                            formatCurrency={formatCurrency}
                            userPlan={userPlan}
                        />
                    )}
                    {activeTab === 'upcoming' && <UpcomingFeatures />}
                </div>
            </main>

            {isLoggedIn && !onboardingComplete && (
                <OnboardingModal onComplete={(name, lang, period, limit) => {
                    setUserName(name);
                    setLanguage(lang);
                    setSpendingPeriod(period);
                    setSpendingLimit(limit);
                    setOnboardingComplete(true);
                    localStorage.setItem('nova_onboarding_complete', 'true');
                    addToast("Core initialized. Welcome to Nova.", "success");
                }} />
            )}

            {/* FIRST ACCOUNT ONBOARDING - Triggers after profile setup if NO accounts exist */}
            {isLoggedIn && onboardingComplete && accounts.length === 0 && (
                <FirstAccountOnboarding onAdd={handleAddAccount} userName={userName} />
            )}

            {/* FIRST TRANSACTION ONBOARDING - Triggers after profile setup AND account creation if no transactions exist */}
            {isLoggedIn && onboardingComplete && accounts.length > 0 && transactions.length === 0 && (
                <FirstTransactionOnboarding 
                    onAdd={handleAddTransaction} 
                    userName={userName} 
                    accounts={accounts}
                />
            )}

            {/* Mobile Nav - Only render if onboarding is complete */}
            {onboardingComplete && (
                <MobileNav 
                    activeTab={activeTab} 
                    onNavigate={handleNavigate} 
                    onAddTransaction={() => handleNavigate('transactions')} 
                />
            )}

            <ToastContainer toasts={toasts} onRemove={removeToast} />

            {/* Floating Assistant - Only render if onboarding is complete */}
            {onboardingComplete && (
                <FloatingAssistant 
                    transactions={transactions} 
                    budgets={budgets} 
                    userPlan={userPlan} 
                    botMode={botMode}
                    onOpenChat={(q) => { setPendingChatQuery(q); handleNavigate('insights'); }}
                    isVisible={activeTab !== 'insights'}
                    insightUsage={insightUsage}
                />
            )}

            {isLogoutModalOpen && (
                <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-fade-in">
                    <div className="bg-slate-900 border border-white/10 rounded-2xl p-6 w-full max-w-sm shadow-2xl animate-slide-up">
                        <h3 className="text-lg font-bold text-white mb-2">Terminate Session?</h3>
                        <p className="text-slate-400 text-sm mb-6">Your local data will persist, but you will need to re-authenticate to access the vault.</p>
                        <div className="flex justify-end gap-3">
                            <button onClick={() => setIsLogoutModalOpen(false)} className="px-4 py-2 text-slate-300 hover:text-white font-medium">Cancel</button>
                            <button 
                                onClick={() => {
                                    setIsLoggedIn(false);
                                    setIsLogoutModalOpen(false);
                                    localStorage.removeItem('nova_auth_token');
                                }} 
                                className="px-4 py-2 bg-rose-600 hover:bg-rose-500 text-white rounded-lg font-bold shadow-lg"
                            >
                                Logout
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    </div>
  );
};

export default App;

